INSERT INTO "program" ("id", "title", "slug", "short_description", "content", "thumbnail", "meta_title", "meta_description", "is_published", "created_at", "updated_at", "field_id", "thumbnail_file_id") VALUES
  
  ('a1b2c3d4-e5f6-4a7b-8c9d-012345678901', 'Ươm tạo khởi nghiệp sáng tạo', 'uom-tao-khoi-nghiep-sang-tao', 'Từ ý tưởng đến mô hình có thể thử nghiệm và thương mại hóa. Hỗ trợ dự án hoàn thiện mô hình kinh doanh, phát triển sản phẩm thử nghiệm, kiểm chứng thị trường và kết nối nguồn lực để thương mại hóa.', '{"version":1,"blocks":[{"id":"8a0a76eb-ccc6-4866-a50c-594aaec097c0","type":"heading","level":2,"text":"ƯƠM TẠO KHỞI NGHIỆP SÁNG TẠO"},{"id":"9945492b-15fc-4641-b240-f3eafa27c12b","type":"paragraph","text":"Từ ý tưởng đến mô hình có thể thử nghiệm và thương mại hóa"},{"id":"9c810035-312c-4328-8379-cbbfc04fa60e","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai hỗ trợ cá nhân, nhóm dự án, startup, hợp tác xã và doanh nghiệp từng bước kiểm chứng ý tưởng, hoàn thiện mô hình kinh doanh, phát triển sản phẩm thử nghiệm và tiếp cận các nguồn lực phù hợp."},{"id":"f3d2b4e9-e2c6-4036-9ef4-af4b9c8cf4e8","type":"paragraph","text":"Mục tiêu của chương trình không chỉ là hoàn thiện một bản kế hoạch, mà giúp dự án trả lời được những câu hỏi quan trọng: Sản phẩm giải quyết vấn đề gì? Ai sẵn sàng sử dụng? Mô hình có khả thi không? Và cần làm gì tiếp theo để đưa sản phẩm vào thực tế?"},{"id":"0680c8f2-2a82-464c-939e-e4683804573d","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image110.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Ông Trần Tuấn Cường đang nêu những khó khăn đang gặp phải tại Gia Lai","caption":"Ông Trần Tuấn Cường đang nêu những khó khăn đang gặp phải tại Gia Lai"},{"id":"a6205f6d-c422-4270-b500-856ae7b2136b","type":"heading","level":2,"text":"Ý TƯỞNG TỐT VẪN CẦN MỘT LỘ TRÌNH ĐÚNG"},{"id":"76750002-f4e1-425c-92fd-ca228b6cad32","type":"paragraph","text":"Nhiều ý tưởng khởi nghiệp được hình thành từ những vấn đề gần gũi trong đời sống, sản xuất và nhu cầu của địa phương. Tuy nhiên, để biến ý tưởng thành một dự án có khả năng phát triển, đội ngũ sáng lập thường gặp phải những điểm nghẽn:"},{"id":"4d8f7f7d-2c74-4558-bfc8-8d71c838e388","type":"paragraph","text":"Chưa xác định rõ khách hàng và nhu cầu thực tế."},{"id":"2140671a-c3b2-4a06-ad4b-d32c28a71c07","type":"paragraph","text":"Chưa biết cách kiểm chứng tính khả thi của ý tưởng."},{"id":"7b93c76e-fe97-488c-9df7-fa3ce123641f","type":"paragraph","text":"Sản phẩm còn ở dạng khái niệm, chưa có phiên bản thử nghiệm."},{"id":"aa701abc-6c64-427f-8261-1e9821700379","type":"paragraph","text":"Mô hình kinh doanh và phương án tạo doanh thu chưa rõ ràng."},{"id":"22769b4c-a879-4466-8306-58526123b7b5","type":"paragraph","text":"Thiếu kinh nghiệm về quản trị, tài chính, pháp lý và thị trường."},{"id":"84fb2a05-da9a-48e7-8c59-270bb5ff2522","type":"paragraph","text":"Chưa tiếp cận được công nghệ, chuyên gia và đối tác phù hợp."},{"id":"083ea3c8-a92e-4012-bae7-2bdee57fa678","type":"paragraph","text":"Chưa có hồ sơ đủ thuyết phục để giới thiệu dự án."},{"id":"71959f42-48ad-4549-9121-2a14002999cd","type":"paragraph","text":"Chương trình ươm tạo giúp dự án nhận diện đúng điểm nghẽn, xác định việc cần ưu tiên và xây dựng lộ trình phát triển phù hợp với nguồn lực hiện có."},{"id":"c116d9b5-abd9-49ed-b094-db55c8a31071","type":"heading","level":2,"text":"ĐỐI TƯỢNG THAM GIA"},{"id":"0b51c704-4fc0-4d61-9f2a-9117cc7074ec","type":"paragraph","text":"Cá nhân và nhóm có ý tưởng"},{"id":"fb874ffe-ee74-4696-977c-ad531d1a5abd","type":"paragraph","text":"Có ý tưởng giải quyết một vấn đề thực tế nhưng chưa biết bắt đầu hoặc chưa hình thành mô hình kinh doanh."},{"id":"5abee582-573c-4ff5-aa81-03d0a7767d92","type":"paragraph","text":"Startup và dự án khởi nghiệp"},{"id":"2c8d851d-bd81-4788-99ab-b364df9e4c75","type":"paragraph","text":"Đã có sản phẩm ban đầu, cần kiểm chứng thị trường, hoàn thiện mô hình hoặc chuẩn bị cho giai đoạn phát triển tiếp theo."},{"id":"80d3887e-0c98-4c1e-bc68-863362c507dd","type":"paragraph","text":"Sinh viên và nhóm nghiên cứu"},{"id":"b3690252-b071-47cf-b8e3-c2a89dbfe383","type":"paragraph","text":"Có sáng kiến, kết quả nghiên cứu hoặc sản phẩm công nghệ cần đánh giá khả năng ứng dụng và thương mại hóa."},{"id":"29f54e20-df37-4f28-b0f0-16213952cdbb","type":"paragraph","text":"Hợp tác xã và doanh nghiệp"},{"id":"ff265897-40c6-46b1-aaba-16daae6f4371","type":"paragraph","text":"Muốn đổi mới sản phẩm, quy trình, phương thức vận hành hoặc phát triển mô hình kinh doanh mới trên nền tảng công nghệ."},{"id":"f3b07170-f6cd-4031-b96c-f06d8fea00f8","type":"heading","level":2,"text":"HÀNH TRÌNH ƯƠM TẠO"},{"id":"f1dedcd7-ed1e-4e60-87f0-9b8f1c2b99bc","type":"heading","level":3,"text":"01. Tiếp nhận và đánh giá"},{"id":"135d08bd-0162-4c70-aad8-31af2ac41d09","type":"paragraph","text":"Tìm hiểu ý tưởng, đội ngũ, sản phẩm, thị trường dự kiến và những khó khăn dự án đang gặp phải. Kết quả đánh giá giúp xác định giai đoạn phát triển và nội dung cần ưu tiên."},{"id":"6209021c-5059-474c-99bf-f7dd1194ef93","type":"heading","level":3,"text":"02. Kiểm chứng vấn đề và khách hàng"},{"id":"2f508935-2de9-48dd-9554-9ac573c1cd0d","type":"paragraph","text":"Làm rõ đối tượng khách hàng, nhu cầu cần giải quyết và giá trị mà sản phẩm mang lại. Dự án được định hướng khảo sát, phỏng vấn và thu thập phản hồi từ người dùng thực tế."},{"id":"89376702-cee6-4eb9-829e-986a92ce8226","type":"heading","level":3,"text":"03. Hoàn thiện mô hình kinh doanh"},{"id":"9ca88837-1fb7-453d-88fb-54c69dbab680","type":"paragraph","text":"Xác định khách hàng mục tiêu, giá trị cốt lõi, nguồn doanh thu, cơ cấu chi phí, kênh tiếp cận thị trường và những nguồn lực cần thiết."},{"id":"b7641e8c-9a7d-427e-bd9e-93bcfefff51b","type":"heading","level":3,"text":"04. Phát triển sản phẩm thử nghiệm"},{"id":"20843904-5509-4057-a41e-6ff57e28400e","type":"paragraph","text":"Hỗ trợ dự án xây dựng mô hình mẫu, phiên bản khả dụng tối thiểu (MVP) hoặc bản chứng minh tính khả thi của giải pháp (POC)."},{"id":"4b78c7c5-4754-4831-83e5-08fe06586e65","type":"paragraph","text":"Tùy theo nhu cầu, dự án có thể được kết nối với năng lực công nghệ trong hệ sinh thái VDCD Group như AI, phần mềm, dữ liệu, UAV, GIS, mô hình 3D và hạ tầng tính toán."},{"id":"f4ecc2d4-1d7b-47fd-9c7b-cd4239c0549c","type":"heading","level":3,"text":"05. Thử nghiệm và hoàn thiện"},{"id":"45eead75-571f-406a-96cb-473aaf5da21c","type":"paragraph","text":"Đưa sản phẩm đến nhóm người dùng hoặc đối tác tiềm năng để thu thập phản hồi, đánh giá khả năng sử dụng và tiếp tục điều chỉnh sản phẩm, phương án vận hành và chiến lược thị trường."},{"id":"dac0549c-636a-4e5c-bff7-ff539c4f4c54","type":"heading","level":3,"text":"06. Trình bày và kết nối nguồn lực"},{"id":"1ea5b58b-a7de-4a22-ae84-30b8db5e0004","type":"paragraph","text":"Hoàn thiện hồ sơ giới thiệu, nội dung thuyết trình và kế hoạch phát triển. Những dự án phù hợp có thể được giới thiệu đến chuyên gia, doanh nghiệp, đơn vị công nghệ, chương trình hỗ trợ hoặc nguồn lực đầu tư."},{"id":"db8b2649-f7a5-486e-9392-dbb8f9e4147a","type":"heading","level":2,"text":"DỰ ÁN ĐƯỢC HỖ TRỢ NHỮNG GÌ?"},{"id":"03987910-fbfe-423b-a877-fa43a645d457","type":"paragraph","text":"Sản phẩm và mô hình kinh doanh"},{"id":"1eea8b5b-9876-43ac-913f-eaf5826a4d2a","type":"paragraph","text":"Làm rõ vấn đề, giá trị khác biệt, khách hàng mục tiêu, phương thức tạo doanh thu và khả năng mở rộng của dự án."},{"id":"eb834231-3261-433f-9c3e-310eb4955cd7","type":"paragraph","text":"Công nghệ và phát triển giải pháp"},{"id":"08f8426f-363e-44d3-b592-0be30d1aaa71","type":"paragraph","text":"Kết nối đội ngũ kỹ thuật, công nghệ và hạ tầng phù hợp để hỗ trợ hoàn thiện sản phẩm mẫu hoặc phiên bản thử nghiệm."},{"id":"748489e7-824c-4898-a5b9-743f8b789db2","type":"paragraph","text":"Thị trường và vận hành"},{"id":"fb44252a-3e0f-46cd-a28c-5934ba3f3aa3","type":"paragraph","text":"Xây dựng cách tiếp cận khách hàng, kế hoạch truyền thông, phương án vận hành, tài chính và sử dụng nguồn lực."},{"id":"5dd35cf2-ced9-44cc-a22f-9e3dcd0b2e75","type":"paragraph","text":"Chuyên gia và hệ sinh thái"},{"id":"5e3e6f8b-1f49-4572-9a8e-5f2367f8183f","type":"paragraph","text":"Kết nối chuyên gia, cố vấn, doanh nghiệp, trường đại học, tổ chức nghiên cứu và đối tác có khả năng hỗ trợ dự án trong từng giai đoạn."},{"id":"c9aaa600-d891-4646-9440-62dc7274d3da","type":"paragraph","text":"Mỗi dự án có một điểm xuất phát khác nhau. Sau bước đánh giá ban đầu, Trung tâm Đổi mới Sáng tạo Gia Lai sẽ đề xuất nội dung và lộ trình phù hợp, thay vì áp dụng một chương trình giống nhau cho tất cả."},{"id":"6543e777-37f5-4379-a6ae-5ca6f8997e93","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image115.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Ông Cao Quân Vũ trực tiếp tư vấn cho các doanh nghiệp địa phương","caption":"Ông Cao Quân Vũ trực tiếp tư vấn cho các doanh nghiệp địa phương"},{"id":"8bb3a9e3-6665-4127-9276-c9818f4bf216","type":"heading","level":2,"text":"KẾT QUẢ DỰ ÁN HƯỚNG ĐẾN"},{"id":"3201f5af-d220-4ec3-81d7-816062bd8960","type":"paragraph","text":"Tùy theo mức độ phát triển, dự án có thể hoàn thiện một hoặc nhiều đầu ra:"},{"id":"a188a1af-09b4-46fd-b6d9-2dcd09c031da","type":"paragraph","text":"Định vị và hồ sơ dự án rõ ràng."},{"id":"5b105dcd-9d25-4f50-85f7-3d8ce8acd01d","type":"paragraph","text":"Kết quả kiểm chứng nhu cầu khách hàng."},{"id":"014f6773-3131-46b2-acef-133e89965399","type":"paragraph","text":"Mô hình kinh doanh được hoàn thiện."},{"id":"696394b8-0dda-4f0c-a359-97e67f48dfbc","type":"paragraph","text":"Sản phẩm mẫu, MVP hoặc POC."},{"id":"902d511b-6bc6-45ee-b740-8e8ca0fbe468","type":"paragraph","text":"Kế hoạch tiếp cận và thử nghiệm thị trường."},{"id":"fffd9322-e290-4e50-8080-b7f96b7ee219","type":"paragraph","text":"Phương án vận hành và tài chính ban đầu."},{"id":"f4286749-480e-486c-82c8-616d91e817ea","type":"paragraph","text":"Bộ hồ sơ hoặc bài thuyết trình dự án."},{"id":"561935f6-fe15-4813-bfa9-ec34e9b490eb","type":"paragraph","text":"Lộ trình phát triển trong giai đoạn tiếp theo."},{"id":"ae32371f-cf31-4b80-9190-4dbe4d30801c","type":"paragraph","text":"Mạng lưới chuyên gia, doanh nghiệp và đối tác phù hợp."},{"id":"bddd0243-788b-47c9-b6c6-3b8caa6528d2","type":"paragraph","text":"Kết quả của chương trình được đánh giá bằng mức độ dự án hiểu thị trường rõ hơn, sản phẩm cụ thể hơn và xác định được bước đi tiếp theo."},{"id":"b03625eb-9fdf-41fd-b7a9-c068d3eac88b","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image101.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Startup trao đổi về ý tưởng mới tại hội thảo.","caption":"Startup trao đổi về ý tưởng mới tại hội thảo."},{"id":"9db9c289-d225-45b0-a723-8f17e18853be","type":"heading","level":2,"text":"HỆ SINH THÁI ĐỒNG HÀNH CÙNG DỰ ÁN"},{"id":"413ce60e-6cd5-4309-be6b-492d12413770","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai kết nối nguồn lực trong hệ sinh thái VDCD Group, bao gồm:"},{"id":"4ccaa86a-1aa7-4ad7-90af-cf9105f3d2ef","type":"paragraph","text":"Mạng lưới chuyên gia và cố vấn đa lĩnh vực."},{"id":"19459378-2751-412b-8ca0-3b6dcc102983","type":"paragraph","text":"Đội ngũ nghiên cứu, kỹ thuật và phát triển sản phẩm."},{"id":"cb951ad6-1df4-4d83-a703-4a4dafe0cd7d","type":"paragraph","text":"Năng lực về UAV, AI, GIS, phần mềm và dữ liệu."},{"id":"7b6c7635-3fff-4b16-86f3-e40bbc3d41c4","type":"paragraph","text":"Hạ tầng trung tâm dữ liệu và tính toán."},{"id":"28891fee-3424-40f6-808a-ed398e4d91a6","type":"paragraph","text":"Doanh nghiệp, trường đại học và tổ chức nghiên cứu."},{"id":"7468da06-4242-4e2d-896e-9e50aae86f37","type":"paragraph","text":"Đối tác thị trường, truyền thông và thương mại."},{"id":"2e5bc2a4-03d2-4731-bdf6-96300fb400f7","type":"paragraph","text":"Trung tâm đóng vai trò tổ chức, định hướng và kết nối nguồn lực; đội ngũ sáng lập vẫn là chủ thể trực tiếp phát triển sản phẩm và đưa dự án vào thực tế."},{"id":"ad39f54b-e81a-43ef-818b-44c73974b273","type":"heading","level":2,"text":"ĐƯA Ý TƯỞNG ĐI XA HƠN BẰNG NHỮNG BƯỚC ĐI CỤ THỂ"},{"id":"29ce6384-87ae-4f54-974a-c0f260c9210b","type":"paragraph","text":"Khởi nghiệp sáng tạo không bắt đầu bằng một kế hoạch hoàn hảo. Nó bắt đầu bằng việc hiểu đúng vấn đề, kiểm chứng từng giả định và liên tục hoàn thiện sản phẩm từ phản hồi thực tế."},{"id":"5c79db68-2b9e-4a49-91bc-a319f86abaa7","type":"heading","level":2,"text":"ĐĂNG KÝ THAM GIA CHƯƠNG TRÌNH ƯƠM TẠO"},{"id":"1a2ceade-9963-4f90-9335-67e05b07283a","type":"paragraph","text":"Gửi thông tin về ý tưởng, đội ngũ, sản phẩm hiện có và nhu cầu cần hỗ trợ. Trung tâm Đổi mới Sáng tạo Gia Lai sẽ tiếp nhận, đánh giá ban đầu và trao đổi về lộ trình phù hợp."},{"id":"a6945f34-03ca-4499-ba2e-8fad169d2196","type":"heading","level":3,"text":"Đưa ý tưởng đi xa hơn bằng những bước đi cụ thể"},{"id":"210c158c-d581-4546-a2c0-fd277a74aadd","type":"paragraph","text":"Gửi thông tin về ý tưởng, đội ngũ, sản phẩm hiện có và nhu cầu cần hỗ trợ. Trung tâm Đổi mới Sáng tạo Gia Lai sẽ tiếp nhận, đánh giá ban đầu và trao đổi về lộ trình phù hợp."},{"id":"a88db5ce-8aec-4dbd-9a92-f858988bba68","type":"cta","label":"GỬI HỒ SƠ DỰ ÁN","url":"/contact"},{"id":"72d97194-50a3-4d34-af25-8b4a423c25f9","type":"cta","label":"TRAO ĐỔI VỚI TRUNG TÂM","url":"/contact"}]}'::jsonb, 'https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/hd_images/ai_thong_minh.png?tr=w-1200,q-85,f-auto', 'Ươm tạo khởi nghiệp sáng tạo | VDCD Gia Lai', 'Hỗ trợ dự án hoàn thiện mô hình kinh doanh, phát triển sản phẩm thử nghiệm, kiểm chứng thị trường và kết nối nguồn lực để thương mại hóa.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'c0110001-0000-4000-a000-000000000001', 'program-thumb-uom-tao-khoi-nghiep-sang-tao'),
  ('a1b2c3d4-e5f6-4a7b-8c9d-012345678902', 'Đào tạo công nghệ và chuyển đổi số', 'dao-tao-cong-nghe-va-chuyen-doi-so', 'Chương trình đào tạo theo nhu cầu thực tế về chuyển đổi số, UAV, AI, GIS, BIM và quản trị dữ liệu số cho doanh nghiệp và các sở ban ngành.', '{"version":1,"blocks":[{"id":"d82c0c86-9730-44f5-a24a-fd139ff13c5f","type":"heading","level":2,"text":"ĐÀO TẠO"},{"id":"b1dbf14d-3f1e-44b2-bc20-415fc43cd053","type":"paragraph","text":"Học để hiểu, thực hành để làm được"},{"id":"62706019-77d9-4c18-bed1-f33ad6d38383","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai tổ chức các chương trình đào tạo gắn với nhu cầu thực tế của cơ quan, doanh nghiệp, trường học và đội ngũ triển khai tại địa phương."},{"id":"61c8f7c8-5df9-4d45-a567-80d12382438c","type":"paragraph","text":"Nội dung được xây dựng theo từng nhóm đối tượng, kết hợp kiến thức nền tảng, tình huống thực tế và hoạt động thực hành. Mục tiêu sau đào tạo không chỉ là hiểu thêm về công nghệ, mà là biết cách lựa chọn, vận hành và đưa công nghệ vào công việc cụ thể."},{"id":"8fe6f3a9-34d5-4bbe-a34e-8d8274287fcd","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image57.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Ông Dương Đức Cảnh - Phó viện trưởng viện thiết kế số, Phó GIÁM ĐỐC TRUNG TÂM ĐÀO TẠO VÀ CHUYỂN GIAO CÔNG NGHỆ","caption":"Ông Dương Đức Cảnh - Phó viện trưởng viện thiết kế số, Phó GIÁM ĐỐC TRUNG TÂM ĐÀO TẠO VÀ CHUYỂN GIAO CÔNG NGHỆ"},{"id":"9a10bd86-83d1-42b9-8684-0562257fa745","type":"heading","level":2,"text":"ĐÀO TẠO BẮT ĐẦU TỪ NHU CẦU THỰC TẾ"},{"id":"f786dc18-1614-4940-bcdd-e7e0309e93a5","type":"paragraph","text":"Mỗi đơn vị có một điểm xuất phát khác nhau. Có nơi cần trang bị kiến thức nền tảng về chuyển đổi số; có đội ngũ cần nâng cao kỹ năng vận hành thiết bị; cũng có doanh nghiệp muốn đào tạo nhân sự để triển khai một giải pháp mới."},{"id":"3bde1819-9ff1-4b4f-a0e7-9922e112d6f6","type":"paragraph","text":"Nếu nội dung đào tạo không gắn với công việc, kiến thức sẽ khó được áp dụng sau chương trình. Vì vậy, Trung tâm Đổi mới Sáng tạo Gia Lai tiếp cận đào tạo theo ba nguyên tắc:"},{"id":"2093e372-49af-43eb-8f47-2e4e418a19db","type":"paragraph","text":"Đúng đối tượng: Nội dung phù hợp với vai trò và trình độ người học."},{"id":"bdcc2ce4-daf7-4c9b-94a0-9beac3ff92af","type":"paragraph","text":"Đúng nhu cầu: Tập trung vào những vấn đề đơn vị đang cần giải quyết."},{"id":"b8475656-2885-4975-89b7-009b878a6e30","type":"paragraph","text":"Có thực hành: Kết hợp tình huống, dữ liệu, thiết bị hoặc phần mềm thực tế."},{"id":"1830b19d-b473-4d1d-9607-70d0a2adeea9","type":"heading","level":2,"text":"ĐỐI TƯỢNG ĐÀO TẠO"},{"id":"49b43b34-2586-4831-9aaa-c68da938cdc0","type":"paragraph","text":"Cơ quan và đơn vị quản lý"},{"id":"062d5340-be2a-4f9d-a4d9-716469094baf","type":"paragraph","text":"Nâng cao nhận thức về chuyển đổi số, quản trị dữ liệu và khả năng ứng dụng công nghệ trong công tác chuyên môn."},{"id":"7d8927f2-5bc6-4f03-a10a-01e0422623f4","type":"paragraph","text":"Doanh nghiệp và hợp tác xã"},{"id":"18ecdc3c-5ebc-411e-8e33-01102113b24d","type":"paragraph","text":"Trang bị kiến thức, kỹ năng và phương pháp để cải tiến quy trình, khai thác dữ liệu và nâng cao hiệu quả vận hành."},{"id":"8be86430-3864-46cd-aee5-be258b749a7c","type":"paragraph","text":"Đội ngũ kỹ thuật"},{"id":"805097f4-e129-4a75-9d6c-c3949cdf446c","type":"paragraph","text":"Đào tạo vận hành thiết bị, thu thập dữ liệu hiện trường, xử lý nội nghiệp và sử dụng các nền tảng công nghệ chuyên môn."},{"id":"d561bf7e-2e42-4c37-acf5-109ff0c60bad","type":"paragraph","text":"Sinh viên và người trẻ"},{"id":"579395ea-b1fc-4697-916b-f9a7110ae4d0","type":"paragraph","text":"Tiếp cận công nghệ mới, rèn luyện kỹ năng thực hành và hiểu rõ hơn nhu cầu nhân lực trong môi trường số."},{"id":"97837190-f087-4c32-b6a4-555cc2946153","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image62.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"https://www.facebook.com/share/1GqPWZPHFJ/Đào tạo Bim cho các nhân sự của doanh nghiệp tại địa phương","caption":"https://www.facebook.com/share/1GqPWZPHFJ/Đào tạo Bim cho các nhân sự của doanh nghiệp tại địa phương"},{"id":"15f8a7b9-8f90-499c-8b69-163ef63c81a0","type":"heading","level":2,"text":"CÁC NHÓM CHƯƠNG TRÌNH ĐÀO TẠO"},{"id":"70dc1c4c-7db4-4b1f-b671-60ff276ee6ed","type":"paragraph","text":"Chuyển đổi số và quản trị dữ liệu"},{"id":"45827e39-e5c2-4168-8fa8-471ff20d7358","type":"paragraph","text":"Giúp học viên hiểu đúng về chuyển đổi số, nhận diện các quy trình có thể cải tiến và xây dựng tư duy quản lý dựa trên dữ liệu."},{"id":"68fba2e6-b6f0-42a6-af30-6518a6a26050","type":"paragraph","text":"Nội dung có thể bao gồm:"},{"id":"e625a49a-c4ce-49df-9701-dfd02cd6c287","type":"paragraph","text":"Nhận thức và tư duy chuyển đổi số."},{"id":"dd1abfcf-5a92-4020-a6ba-fc5e8b65772f","type":"paragraph","text":"Số hóa quy trình và hồ sơ."},{"id":"aa7361f5-75c9-4e04-a7cc-0767de5b5bdd","type":"paragraph","text":"Thu thập, chuẩn hóa và quản trị dữ liệu."},{"id":"f4c47a81-f9c7-44c1-9f87-f7e0c842fbe9","type":"paragraph","text":"An toàn và khai thác dữ liệu trong hoạt động."},{"id":"f89b00c3-26f8-48b1-877a-da04e46a5cf0","type":"paragraph","text":"Ứng dụng nền tảng số vào quản lý, sản xuất và kinh doanh."},{"id":"4489c85c-7693-4199-b129-209608aea719","type":"paragraph","text":"UAV, bản đồ số và GIS"},{"id":"e1fc3cf8-5a7d-4a95-8ff2-ec8112e45255","type":"paragraph","text":"Trang bị kiến thức từ vận hành thiết bị ngoài thực địa đến xử lý, kiểm tra và khai thác dữ liệu sau thu thập."},{"id":"3f10c188-2ed2-4db9-8d19-c75e4c80027f","type":"paragraph","text":"Nội dung có thể bao gồm:"},{"id":"dbca0257-6566-478b-8770-dfaff4be50aa","type":"paragraph","text":"Kiến thức cơ bản và an toàn vận hành UAV."},{"id":"135af5c9-c6bd-4875-9613-39a3b6e74ad3","type":"paragraph","text":"Lập kế hoạch bay và thu thập dữ liệu hiện trường."},{"id":"f4188152-5bdb-4afb-932b-01488d66e0a7","type":"paragraph","text":"Sử dụng GNSS và thiết lập điểm khống chế."},{"id":"8d143e3e-372a-4325-9469-3ec31ea7ce9a","type":"paragraph","text":"Xử lý bình đồ ảnh, mô hình 2D và 3D."},{"id":"7d00e9c0-63e4-4d1d-ba8b-8dd7573db767","type":"paragraph","text":"Biên tập, quản lý và khai thác dữ liệu trên GIS."},{"id":"608773dc-b970-4541-b0cd-8e655774304a","type":"paragraph","text":"Phối hợp giữa công tác ngoại nghiệp và nội nghiệp."},{"id":"62e57800-0508-4477-a914-90540e0421d7","type":"paragraph","text":"AI, phần mềm và khai thác dữ liệu"},{"id":"dbb86d4f-117e-4b14-9edc-df6adf182186","type":"paragraph","text":"Giúp học viên hiểu khả năng ứng dụng AI và phần mềm vào từng bài toán cụ thể, từ nhận diện hình ảnh đến tự động hóa quy trình."},{"id":"aa25f397-8098-4797-bd24-ac65196393e7","type":"paragraph","text":"Nội dung có thể bao gồm:"},{"id":"d833b595-1c65-4de2-a96c-f351b2afb118","type":"paragraph","text":"Kiến thức nền tảng về AI và dữ liệu."},{"id":"2c81bddd-3550-4db5-80a3-e8c8d4be9b0a","type":"paragraph","text":"Ứng dụng AI trong phân tích hình ảnh, video."},{"id":"6662ae69-1586-44b9-bd15-6abe3f974c6f","type":"paragraph","text":"Nhận diện, đếm và phân loại đối tượng."},{"id":"176d25e4-d9a2-4e12-95b8-37a94c9f3875","type":"paragraph","text":"Sử dụng phần mềm và dashboard quản lý."},{"id":"846c9f99-ceff-4bb7-9671-37fe40bf3869","type":"paragraph","text":"Khai thác dữ liệu phục vụ báo cáo và ra quyết định."},{"id":"9fe12216-d08f-4eca-ab69-1d1cf296aab1","type":"paragraph","text":"Sử dụng AI có trách nhiệm và kiểm soát kết quả đầu ra."},{"id":"c351c6c4-ea04-4c1e-a41d-581600db4a90","type":"paragraph","text":"Khởi nghiệp và đổi mới sáng tạo"},{"id":"52da61cd-0e52-4a04-9d29-56ccf6ea6cff","type":"paragraph","text":"Trang bị phương pháp giúp cá nhân và nhóm dự án phát triển ý tưởng theo hướng thực tế hơn."},{"id":"92231195-05db-43ed-a5ec-97173966208d","type":"paragraph","text":"Nội dung có thể bao gồm:"},{"id":"19bd79f1-dbba-461f-a4fe-9752cd35a49d","type":"paragraph","text":"Xác định vấn đề và khách hàng mục tiêu."},{"id":"52b594d9-55b6-4a97-8fb0-f9ed60f994a3","type":"paragraph","text":"Xây dựng mô hình kinh doanh."},{"id":"268a4e5a-e890-4788-bd55-020761d4928b","type":"paragraph","text":"Phát triển sản phẩm thử nghiệm."},{"id":"035fa987-5d46-43ce-b6f5-4e79a9968b62","type":"paragraph","text":"Kiểm chứng nhu cầu thị trường."},{"id":"08ac48dc-0728-49c4-9f4a-648f21d2e6fa","type":"paragraph","text":"Xây dựng thương hiệu và kế hoạch tiếp cận khách hàng."},{"id":"9c32df38-e787-4443-9392-b3ff139928ab","type":"paragraph","text":"Hoàn thiện hồ sơ và kỹ năng trình bày dự án."},{"id":"3e3ed778-b020-4832-a1bf-3449f69a3d6e","type":"paragraph","text":"Phần đào tạo cung cấp kiến thức và công cụ thực hành. Những dự án cần đồng hành chuyên sâu từ ý tưởng đến thương mại hóa sẽ được định hướng sang chương trình Ươm tạo khởi nghiệp sáng tạo."},{"id":"c568e04a-8475-44b7-9820-18f8b5209e84","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image112.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Hơn 600+ học viên đến từ các sở ban ngành tham dự buổi đạo tào","caption":"Hơn 600+ học viên đến từ các sở ban ngành tham dự buổi đạo tào"},{"id":"d29f3122-cc15-45ef-9321-ffe68a52cbf1","type":"heading","level":2,"text":"QUY TRÌNH XÂY DỰNG CHƯƠNG TRÌNH"},{"id":"eec6449b-b721-4755-83f8-ea86cb8c0bd5","type":"heading","level":3,"text":"01. Khảo sát nhu cầu"},{"id":"5366dc28-b0e0-4b66-b2f9-ef0235a6ab0e","type":"paragraph","text":"Tìm hiểu đối tượng học viên, mục tiêu của đơn vị, kiến thức hiện có và vấn đề cần giải quyết sau đào tạo."},{"id":"b42170ff-4a6e-4abd-ba1b-24d28f0d4ddd","type":"heading","level":3,"text":"02. Thiết kế nội dung"},{"id":"137a4f67-ba62-42b2-8e7e-52e9c0ac4a1e","type":"paragraph","text":"Xây dựng chủ đề, thời lượng, hình thức tổ chức và hoạt động thực hành phù hợp với yêu cầu thực tế."},{"id":"f3dd67e6-4b2e-48d9-9f5a-1c3709f0ca7b","type":"heading","level":3,"text":"03. Tổ chức đào tạo"},{"id":"1c8ab51c-a7c0-4bf5-87d5-ada2f2deb479","type":"paragraph","text":"Kết hợp trình bày kiến thức, minh họa công nghệ, trao đổi tình huống và hướng dẫn thực hành."},{"id":"26e002a3-d2bf-43ee-b7e9-fe8fcbdecd46","type":"heading","level":3,"text":"04. Thực hành và xử lý tình huống"},{"id":"9832b028-13f1-4b9a-b093-b534d4c824f1","type":"paragraph","text":"Học viên trực tiếp làm việc với thiết bị, phần mềm, dữ liệu mẫu hoặc bài toán mô phỏng phù hợp với chương trình."},{"id":"52cc3ff7-54de-4cde-a1a8-5dcf48da99c1","type":"heading","level":3,"text":"05. Đánh giá và đề xuất áp dụng"},{"id":"7d73ac29-4f19-44d0-abc6-d4db142f0c3d","type":"paragraph","text":"Đánh giá mức độ tiếp thu, tổng hợp phản hồi và đề xuất những nội dung đơn vị có thể tiếp tục triển khai sau đào tạo."},{"id":"32d50223-346d-4857-bbe5-20143d6a59f2","type":"heading","level":2,"text":"HÌNH THỨC TỔ CHỨC LINH HOẠT"},{"id":"4ee6c881-fa8a-46d0-8496-a1ecc897238e","type":"paragraph","text":"Tùy theo mục tiêu và điều kiện triển khai, chương trình có thể được tổ chức dưới nhiều hình thức:"},{"id":"c8adb7f2-f108-4b46-bc91-9f709db75cd1","type":"paragraph","text":"Hội thảo và chương trình nâng cao nhận thức."},{"id":"6535b9e6-4c5f-404f-bb3d-49c69c2ead15","type":"paragraph","text":"Lớp đào tạo tập trung theo chuyên đề."},{"id":"63b0d74d-71ec-4371-a85e-e297b0d89d9d","type":"paragraph","text":"Đào tạo trực tiếp tại đơn vị."},{"id":"f44f0d2e-1fc7-44fa-a947-9ccb718f9bcd","type":"paragraph","text":"Thực hành ngoài hiện trường."},{"id":"4a6f6b4b-bd87-465a-b357-362ec3a29432","type":"paragraph","text":"Hướng dẫn sử dụng thiết bị và phần mềm."},{"id":"3d43dd6a-110c-4918-a01d-aa63ee09c5a2","type":"paragraph","text":"Chương trình ngắn hạn theo nhu cầu."},{"id":"edc40829-ac62-4460-b8b1-8fbff4e91fbb","type":"paragraph","text":"Đào tạo kết hợp trực tiếp và trực tuyến."},{"id":"3fca4f75-5c34-41cb-af3f-ad33318db5fd","type":"paragraph","text":"Thời lượng và nội dung được điều chỉnh theo nhóm học viên, thay vì sử dụng một giáo trình cố định cho mọi đối tượng."},{"id":"3dac4ca3-3c23-4ac8-b932-fc51ca47bbab","type":"heading","level":2,"text":"KẾT QUẢ SAU ĐÀO TẠO"},{"id":"6228a46f-acdd-4017-87c1-1f68df1eaac9","type":"paragraph","text":"Tùy theo từng chương trình, đơn vị và học viên có thể nhận được:"},{"id":"528fcab3-7550-4bb9-a3a1-eb6a8dd1f0de","type":"paragraph","text":"Chương trình được thiết kế theo nhu cầu."},{"id":"757c6283-4ca3-4a46-bb31-ec4772d5f65f","type":"paragraph","text":"Tài liệu và hướng dẫn thực hành."},{"id":"311ab8e4-7b0f-45a1-9989-43ecc03a90d2","type":"paragraph","text":"Kiến thức nền tảng về lĩnh vực đào tạo."},{"id":"532aa4cb-c101-4191-a7c5-a9fc06b0f797","type":"paragraph","text":"Kỹ năng sử dụng thiết bị hoặc phần mềm."},{"id":"d73b0877-0d95-4923-bbe9-612f834b67cf","type":"paragraph","text":"Bài tập và tình huống gắn với công việc."},{"id":"4c1ccc89-a177-42a9-b6e8-2cb1d617a3a1","type":"paragraph","text":"Kết quả đánh giá mức độ tiếp thu."},{"id":"a4dd0f02-2636-4d04-a32b-ceacf2e9d1a9","type":"paragraph","text":"Đề xuất áp dụng sau chương trình."},{"id":"5cc5a3c5-2a2b-4049-b9e4-73631dff831f","type":"paragraph","text":"Xác nhận hoàn thành nếu chương trình có áp dụng."},{"id":"6b285a0e-aa6c-4487-8dd0-328e920d577d","type":"paragraph","text":"Mỗi chương trình cần xác định rõ học viên sẽ hiểu được gì, làm được gì và có thể áp dụng vào đâu."},{"id":"48603d70-a22a-44f3-b1b3-6bc46b08616d","type":"heading","level":2,"text":"KẾT NỐI CHUYÊN MÔN VÀ CÔNG NGHỆ"},{"id":"2c48f9e9-88b0-4f92-82be-9feab08599b1","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai kết nối nguồn lực trong hệ sinh thái VDCD Group để xây dựng và tổ chức các chương trình phù hợp:"},{"id":"e6302cf2-5b61-4a7e-8d51-83d2f676f48f","type":"paragraph","text":"Mạng lưới chuyên gia, giảng viên và đội ngũ kỹ thuật."},{"id":"6a290286-4349-44c1-9a9e-a80f6be1b63e","type":"paragraph","text":"Kinh nghiệm triển khai công nghệ tại hiện trường."},{"id":"956c6f31-436a-457c-983e-62b81d142116","type":"paragraph","text":"Hệ thống UAV, AI, GIS, phần mềm và dữ liệu."},{"id":"f5fe46b3-0a19-4314-a4dc-f20e4bd890bc","type":"paragraph","text":"Hạ tầng trung tâm dữ liệu và tính toán."},{"id":"87eca356-d7d4-4542-8ba2-bf07e0cabf2f","type":"paragraph","text":"Mạng lưới doanh nghiệp, trường đại học và tổ chức nghiên cứu."},{"id":"0a618ba9-7946-457f-b243-047369953ea0","type":"paragraph","text":"Chuyên gia được lựa chọn theo chủ đề và mục tiêu của chương trình, giúp nội dung đào tạo vừa có nền tảng chuyên môn, vừa gắn với kinh nghiệm triển khai thực tế."},{"id":"f7520e3b-d99d-4bc5-8570-93d4953275bf","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image107.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Chuyên gia đang đào tạo cho nhân sự mới ra trường","caption":"Chuyên gia đang đào tạo cho nhân sự mới ra trường"},{"id":"42ba3b70-7369-41a4-abc7-2ddd0c174aee","type":"heading","level":2,"text":"XÂY DỰNG NĂNG LỰC ĐỂ CÔNG NGHỆ ĐƯỢC ÁP DỤNG THỰC CHẤT"},{"id":"1ef8ab98-595a-4000-906d-96649a266fa1","type":"paragraph","text":"Công nghệ chỉ tạo ra giá trị khi đội ngũ hiểu, sử dụng đúng và có khả năng duy trì trong công việc hằng ngày."},{"id":"4a97a840-5f1d-4d04-8f61-5aa914fcfbed","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai hướng đến các chương trình đào tạo thiết thực, dễ tiếp cận và có khả năng chuyển hóa kiến thức thành năng lực triển khai."},{"id":"f7ffd3b3-e6ba-4829-87c3-aee23db08ba6","type":"heading","level":2,"text":"ĐỀ XUẤT CHƯƠNG TRÌNH ĐÀO TẠO"},{"id":"a5b3ac9f-2f90-4bd9-aff0-a33f86ebe5e7","type":"paragraph","text":"Cơ quan, doanh nghiệp và tổ chức có thể gửi nhu cầu về đối tượng học viên, chủ đề, mục tiêu và hình thức tổ chức. Trung tâm sẽ khảo sát và đề xuất nội dung phù hợp."},{"id":"e4a6b14a-e017-4b02-a6c1-a0bf53744bc1","type":"heading","level":3,"text":"Xây dựng năng lực để công nghệ được áp dụng thực chất"},{"id":"5fb8f301-56f3-4a91-a4d5-0ed9743d3f31","type":"paragraph","text":"Cơ quan, doanh nghiệp và tổ chức có thể gửi nhu cầu về đối tượng học viên, chủ đề, mục tiêu và hình thức tổ chức. Trung tâm sẽ khảo sát và đề xuất nội dung phù hợp."},{"id":"4b829172-b8b9-402b-954c-5d37802c6137","type":"cta","label":"ĐĂNG KÝ NHU CẦU ĐÀO TẠO","url":"/contact"},{"id":"cf2ca2e4-44d6-41c5-84ac-dae628d12f2f","type":"cta","label":"TRAO ĐỔI VỚI TRUNG TÂM","url":"/contact"}]}'::jsonb, 'https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/hd_images/data_center_viet_nam.png?tr=w-1200,q-85,f-auto', 'Đào tạo công nghệ và chuyển đổi số | VDCD Gia Lai', 'Chương trình đào tạo theo nhu cầu thực tế về chuyển đổi số, UAV, AI, GIS, BIM và quản trị dữ liệu số cho doanh nghiệp và các sở ban ngành.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'c0110001-0000-4000-a000-000000000002', 'program-thumb-dao-tao-cong-nghe-va-chuyen-doi-so'),
  ('a1b2c3d4-e5f6-4a7b-8c9d-012345678903', 'Kết nối chuyên gia và hệ sinh thái', 'ket-noi-chuyen-gia-va-he-sinh-thai', 'Kết nối đúng chuyên môn – Tháo gỡ đúng nút thắt – Mở rộng cơ hội hợp tác giữa chính quyền, doanh nghiệp, viện nghiên cứu và trường đại học.', '{"version":1,"blocks":[{"id":"51237bf8-4756-400b-ad4f-ea680e54dfe7","type":"heading","level":2,"text":"KẾT NỐI CHUYÊN GIA"},{"id":"21af7450-fbef-4c1c-80b6-e29eaacd9498","type":"paragraph","text":"Đúng bài toán - Đúng chuyên gia - Đúng thời điểm"},{"id":"6045bcad-ce6e-49d8-a536-e4d2e0d774b3","type":"paragraph","text":"Một vấn đề chỉ có thể được giải quyết hiệu quả khi đơn vị tiếp cận đúng người có chuyên môn, kinh nghiệm và khả năng đồng hành phù hợp."},{"id":"b3c2de3c-8a41-4682-9971-7d3e7ccf7df1","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai kết nối cơ quan, doanh nghiệp, hợp tác xã, startup và tổ chức nghiên cứu với mạng lưới chuyên gia trong nhiều lĩnh vực. Không chỉ giới thiệu thông tin liên hệ, Trung tâm hỗ trợ làm rõ nhu cầu, lựa chọn chuyên gia và tổ chức hình thức trao đổi phù hợp với từng bài toán."},{"id":"63a3e145-d3a9-4c5e-b1f5-d1143ba75541","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image105.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Kí kết hợp tác chiến lược với Vietadge","caption":"Kí kết hợp tác chiến lược với Vietadge"},{"id":"06e713f6-336e-4030-9a2f-b7e8849612a4","type":"heading","level":2,"text":"KHI BÀI TOÁN ĐÃ CÓ NHƯNG CHƯA TÌM ĐƯỢC ĐÚNG NGƯỜI"},{"id":"271278fe-0db3-4777-8635-1af9d2e2600f","type":"paragraph","text":"Trong quá trình triển khai công việc, nhiều đơn vị gặp những nhu cầu như:"},{"id":"8ccd98d6-19a8-4127-b958-c02521826512","type":"paragraph","text":"Cần đánh giá tính khả thi của một ý tưởng hoặc giải pháp."},{"id":"232e228e-6954-4e7e-aa0c-c77f599f85cd","type":"paragraph","text":"Cần ý kiến chuyên môn trước khi triển khai dự án."},{"id":"ac8d4aa3-e995-4038-95ce-e3b943b1dd32","type":"paragraph","text":"Muốn ứng dụng công nghệ nhưng chưa xác định phương án phù hợp."},{"id":"074d0830-200c-4c1c-a8d4-d0bbb4a160f8","type":"paragraph","text":"Cần chuyên gia phản biện sản phẩm, quy trình hoặc mô hình kinh doanh."},{"id":"c7c36cb9-032f-42e3-ba6e-16628741a1ae","type":"paragraph","text":"Cần đối tác có năng lực kỹ thuật để phối hợp triển khai."},{"id":"5fb305bd-5960-4f34-a64d-8fd80de6891c","type":"paragraph","text":"Muốn tiếp cận mạng lưới doanh nghiệp, trường đại học và tổ chức nghiên cứu."},{"id":"4cc8c26e-67f0-4cab-9147-342e5fba29ce","type":"paragraph","text":"Việc tìm được một chuyên gia giỏi chưa chắc đã đủ. Chuyên gia cần có kinh nghiệm phù hợp với lĩnh vực, hiểu đúng vấn đề và tham gia theo hình thức đáp ứng được mục tiêu của đơn vị."},{"id":"cf278e8b-2fa6-45c3-a628-c87e1472ad5d","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai đóng vai trò tiếp nhận bài toán, xác định nhu cầu và kết nối đúng nguồn lực chuyên môn."},{"id":"81af4c75-62c2-489d-a748-5009b88ea47c","type":"heading","level":2,"text":"ĐỐI TƯỢNG KẾT NỐI"},{"id":"2e8aefb2-bee3-4d0e-b97a-3cf90fdbbc48","type":"paragraph","text":"Cơ quan và đơn vị quản lý"},{"id":"1bfed0e2-d3e1-4d25-85a3-09400913ea70","type":"paragraph","text":"Cần ý kiến chuyên môn, phản biện giải pháp hoặc kết nối nguồn lực phục vụ chương trình và dự án tại địa phương."},{"id":"0e846e90-66d8-48fa-8df4-eb72d3e4fdab","type":"paragraph","text":"Doanh nghiệp và hợp tác xã"},{"id":"d427adfe-4c5d-4bd2-9a72-67626e45e074","type":"paragraph","text":"Cần chuyên gia hỗ trợ về công nghệ, vận hành, sản phẩm, thị trường hoặc đổi mới mô hình kinh doanh."},{"id":"6920ca9c-8d02-4197-a1b7-ca2514f5eac6","type":"paragraph","text":"Startup và nhóm dự án"},{"id":"d8d24d28-3be8-4fe8-a949-2c162f67480e","type":"paragraph","text":"Cần cố vấn đánh giá ý tưởng, hoàn thiện sản phẩm, kiểm chứng mô hình và chuẩn bị cho giai đoạn phát triển tiếp theo."},{"id":"0f74ddee-e3e4-4ca3-b096-5dcd7d860d14","type":"paragraph","text":"Trường đại học và tổ chức nghiên cứu"},{"id":"8a85885f-520a-418c-9ff2-7ae34855a808","type":"paragraph","text":"Cần kết nối doanh nghiệp, chuyên gia thực tiễn hoặc đối tác để hợp tác nghiên cứu, chuyển giao và ứng dụng công nghệ."},{"id":"4f72831c-e196-49a6-8f31-53fd9e0f9a93","type":"heading","level":2,"text":"7(5).JPG"},{"id":"b86a2d2b-1821-49ef-bb26-a83667250796","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image114.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Kí kết MOU với Trường Đại học Quy Nhơn","caption":"Kí kết MOU với Trường Đại học Quy Nhơn"},{"id":"d67f8db7-4a0a-4d11-9467-43244510abe4","type":"heading","level":2,"text":"LĨNH VỰC CHUYÊN GIA KẾT NỐI"},{"id":"8b956117-1852-449c-b1a6-aa0ce25e68e8","type":"paragraph","text":"Công nghệ và chuyển đổi số"},{"id":"7513407d-2fa3-4c22-b455-76d495a2f011","type":"paragraph","text":"Xây dựng chiến lược và lộ trình chuyển đổi số."},{"id":"f784dad9-7707-411d-b1cb-5c9d22fb167c","type":"paragraph","text":"Quản trị, số hóa và khai thác dữ liệu."},{"id":"6b6224c7-8ca1-46a2-9bc0-56fef5e2ff8a","type":"paragraph","text":"Phát triển phần mềm và nền tảng quản lý."},{"id":"63becb47-e8ee-4dcc-a50b-572fed4981c0","type":"paragraph","text":"Hạ tầng công nghệ, trung tâm dữ liệu và an toàn thông tin."},{"id":"cbb4bb33-777d-4a3f-aef3-a1fffc2989a4","type":"paragraph","text":"UAV, AI và dữ liệu không gian"},{"id":"70bd24a4-931d-48aa-a6ba-8486fa2740a8","type":"paragraph","text":"UAV, trắc địa và bản đồ số."},{"id":"dc93288b-6b62-4d32-b74c-c3b0f7ff68fe","type":"paragraph","text":"GIS, mô hình 2D, 3D và dữ liệu không gian."},{"id":"facfaa4f-3501-45d8-b2a7-87238c713b5a","type":"paragraph","text":"Trí tuệ nhân tạo và phân tích hình ảnh."},{"id":"0f5b4ba6-4124-478c-b515-a058fd34a7f1","type":"paragraph","text":"Tự động hóa, giám sát và cảnh báo thông minh."},{"id":"ccfe097c-d877-49a3-9040-31c2ac2e9eb3","type":"paragraph","text":"Quản lý và phát triển dự án"},{"id":"b4f78a51-591a-4563-bb65-a8a2550d7df0","type":"paragraph","text":"Xây dựng mô hình tổ chức và vận hành."},{"id":"662fe531-2112-4aea-aecd-aa2c2a40c406","type":"paragraph","text":"Đánh giá tính khả thi của giải pháp."},{"id":"496515cd-b3fb-4f9f-b363-01ba7431580d","type":"paragraph","text":"Quản lý dự án và kiểm soát tiến độ."},{"id":"bf6bcc1d-1b2b-4864-b4e7-858e5c25a4f8","type":"paragraph","text":"Phát triển sản phẩm và ứng dụng công nghệ."},{"id":"800252a7-9e49-49ac-9185-a55d7632e765","type":"paragraph","text":"Khởi nghiệp và thị trường"},{"id":"65e196c8-7b72-469e-9ae3-1bfdc70c55e9","type":"paragraph","text":"Hoàn thiện mô hình kinh doanh."},{"id":"815e2a7b-86a4-436c-99a6-3a6dba4932e6","type":"paragraph","text":"Xây dựng thương hiệu và chiến lược thị trường."},{"id":"18b1c3d5-b37b-4e25-b21c-00344ac2c091","type":"paragraph","text":"Cố vấn sản phẩm và phát triển khách hàng."},{"id":"013e0d25-eba0-47f9-9ebd-309e2a826a4e","type":"paragraph","text":"Hồ sơ dự án và định hướng tiếp cận nguồn lực."},{"id":"80d270c8-abc5-451e-a035-1a1aecb1ddd3","type":"paragraph","text":"Các lĩnh vực chuyên ngành"},{"id":"a61d3c56-1858-467f-83c0-556284e03f88","type":"paragraph","text":"Thông qua hệ sinh thái VDCD Group, Trung tâm có thể kết nối chuyên gia trong các lĩnh vực như trắc địa, xây dựng, quy hoạch, đất đai, tài nguyên, môi trường, nông nghiệp, lâm nghiệp và hạ tầng đô thị."},{"id":"a35cbb35-e555-4fdf-b88a-ed3b75cee23e","type":"heading","level":2,"text":"HÌNH THỨC KẾT NỐI"},{"id":"bcb60bfd-3083-4f6e-8a61-5d0a7c411d32","type":"paragraph","text":"Tùy theo tính chất của từng nhu cầu, hoạt động kết nối có thể được tổ chức dưới nhiều hình thức:"},{"id":"a762c7c2-8051-473f-bf0b-867349ea1c82","type":"paragraph","text":"Trao đổi trực tiếp với chuyên gia"},{"id":"b2da556d-96ac-4f83-af0f-ef3ed0239b15","type":"paragraph","text":"Phù hợp với những vấn đề cụ thể, cần làm rõ hướng tiếp cận hoặc nhận ý kiến chuyên môn ban đầu."},{"id":"1654dcab-7b47-469c-8808-ff00b1a3abc4","type":"paragraph","text":"Phiên tư vấn và phản biện"},{"id":"0012050e-2e68-414f-83eb-6cdb80ca75da","type":"paragraph","text":"Chuyên gia nghiên cứu thông tin, trao đổi với đơn vị và đưa ra nhận định, khuyến nghị hoặc phương án đề xuất."},{"id":"66915704-3187-4cb2-b5d5-19fb6e3b8d89","type":"paragraph","text":"Hội đồng chuyên gia"},{"id":"ee2e3e41-2cec-4bf6-a409-441daba35e14","type":"paragraph","text":"Tập hợp chuyên gia từ nhiều lĩnh vực để đánh giá một dự án, sản phẩm hoặc giải pháp có tính liên ngành."},{"id":"3e127f21-f3f8-4f2e-b27d-c6df8168d8b8","type":"paragraph","text":"Hội thảo và tọa đàm chuyên đề"},{"id":"5006d97b-6b83-41ac-90e4-129ff49165df","type":"paragraph","text":"Tạo không gian trao đổi giữa chuyên gia, cơ quan quản lý, doanh nghiệp và cộng đồng về một chủ đề thực tiễn."},{"id":"1d4062aa-92be-493a-8788-bbe803f1bf63","type":"paragraph","text":"Kết nối hợp tác triển khai"},{"id":"40e7a464-a5c2-4c36-861f-a47ba194c710","type":"paragraph","text":"Giới thiệu chuyên gia, doanh nghiệp hoặc đơn vị kỹ thuật có khả năng tiếp tục tham gia nghiên cứu, thử nghiệm hay phối hợp triển khai."},{"id":"b341abc9-386d-4e32-8608-7659a88e0c0e","type":"paragraph","text":"Hoạt động kết nối tạo cơ hội để các bên gặp gỡ và đánh giá khả năng hợp tác; không đồng nghĩa với cam kết dự án, đầu tư hoặc kết quả thương mại."},{"id":"972ff9de-3b22-4dce-b16b-dfd0de9d3d81","type":"heading","level":2,"text":"QUY TRÌNH KẾT NỐI CHUYÊN GIA"},{"id":"4be1718e-e511-435f-bb9f-8947474ec2b3","type":"heading","level":3,"text":"01. Tiếp nhận nhu cầu"},{"id":"f174cdcd-59af-44e1-85a0-7a0c901fe46a","type":"paragraph","text":"Đơn vị cung cấp thông tin về vấn đề, mục tiêu, lĩnh vực chuyên môn và kết quả mong muốn."},{"id":"5e4c007d-2d61-437c-a67a-3b25bd11230d","type":"heading","level":3,"text":"02. Làm rõ bài toán"},{"id":"be8588f8-3058-489d-9347-c07a6b72003e","type":"paragraph","text":"Trung tâm trao đổi để xác định phạm vi, mức độ chuyên sâu, hình thức làm việc và năng lực chuyên gia cần có."},{"id":"c912df22-e218-4425-83a3-788c13c205cd","type":"heading","level":3,"text":"03. Lựa chọn chuyên gia phù hợp"},{"id":"12025722-a08d-4fe9-9bbf-ea0123d1d698","type":"paragraph","text":"Tìm kiếm và đề xuất chuyên gia dựa trên lĩnh vực chuyên môn, kinh nghiệm thực tế và mức độ phù hợp với yêu cầu."},{"id":"990754ff-85d2-4a8d-9ea1-eaa7e70013eb","type":"heading","level":3,"text":"04. Tổ chức kết nối"},{"id":"1875dafb-c98a-419f-8e67-0c2df56ca7f6","type":"paragraph","text":"Điều phối lịch làm việc, cung cấp thông tin cần thiết và tổ chức buổi trao đổi, tư vấn hoặc phản biện."},{"id":"a566fdee-b0b5-48cd-ad3a-2a796a9406e3","type":"heading","level":3,"text":"05. Theo dõi và mở rộng hợp tác"},{"id":"5e550f27-e669-45c5-8acb-2b1cc71e7476","type":"paragraph","text":"Tổng hợp nội dung trao đổi, tiếp nhận phản hồi và hỗ trợ kết nối các bước tiếp theo nếu hai bên có nhu cầu."},{"id":"9952664b-2f78-47f6-8e96-956fd1f0f5b0","type":"heading","level":2,"text":"GIÁ TRỊ NHẬN ĐƯỢC"},{"id":"291cb597-3748-42a5-90fc-08635cc88972","type":"paragraph","text":"Thông qua hoạt động kết nối, đơn vị có thể:"},{"id":"0279eaa1-51d9-4453-b128-f315c65d9786","type":"paragraph","text":"Tiếp cận chuyên gia phù hợp trong thời gian ngắn hơn."},{"id":"1fd236a3-3ffc-450f-a0e4-e8bb3366074a","type":"paragraph","text":"Nhận góc nhìn độc lập và có cơ sở chuyên môn."},{"id":"6b2313de-328b-4236-85da-924333ef7b4c","type":"paragraph","text":"Nhận diện sớm rủi ro trước khi triển khai."},{"id":"1886f470-b6a4-43ce-8ec8-192c5953537c","type":"paragraph","text":"Làm rõ hướng công nghệ, sản phẩm hoặc mô hình hoạt động."},{"id":"7bd8e550-e92f-4bf5-a436-3030635806ff","type":"paragraph","text":"Mở rộng quan hệ với doanh nghiệp và tổ chức nghiên cứu."},{"id":"5081d431-cfae-4a3c-9cea-4d7fff3b26e3","type":"paragraph","text":"Hình thành cơ hội hợp tác hoặc chuyển giao công nghệ."},{"id":"c63c059e-1a22-44b0-afa0-3ed486565bfc","type":"paragraph","text":"Có cơ sở xác định bước đi tiếp theo cho bài toán của mình."},{"id":"d6f23d5c-cf98-4642-b69b-c711b038e673","type":"heading","level":2,"text":"MẠNG LƯỚI CHUYÊN MÔN ĐA LĨNH VỰC"},{"id":"8d9badba-d2b5-4380-9ac2-47774b721558","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai kết nối mạng lưới chuyên gia, kỹ sư, nhà nghiên cứu, doanh nghiệp công nghệ và các đơn vị thành viên trong hệ sinh thái VDCD Group."},{"id":"bf45a955-0ca8-4872-8413-9e076980193d","type":"paragraph","text":"Nguồn lực đa lĩnh vực giúp Trung tâm không chỉ tìm người có chuyên môn phù hợp, mà còn có khả năng kết nối các nhóm chuyên gia khi bài toán cần sự phối hợp giữa công nghệ, quản lý và thực tiễn triển khai."},{"id":"96f612f1-714a-486c-a649-af5be543cc8c","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image103.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Kí kết MOU với Trường Đại học FPT Quy Nhơn","caption":"Kí kết MOU với Trường Đại học FPT Quy Nhơn"},{"id":"0c0d25e2-5cf4-482d-9aae-4318be0e3c55","type":"heading","level":2,"text":"KẾT NỐI ĐÚNG NGƯỜI ĐỂ BÀI TOÁN ĐI ĐÚNG HƯỚNG"},{"id":"1d479d9f-6709-46b1-85b5-7536d5716e4c","type":"paragraph","text":"Không phải mọi vấn đề đều cần một chương trình đào tạo dài hạn hay một dự án tư vấn tổng thể. Đôi khi, điều đơn vị cần nhất là được tiếp cận đúng chuyên gia để nhìn rõ vấn đề và xác định bước đi tiếp theo."},{"id":"baf40b9f-ddf0-4ef7-a7c1-c686ef2dd69b","type":"heading","level":2,"text":"GỬI NHU CẦU KẾT NỐI CHUYÊN GIA"},{"id":"071397a8-e951-44be-81b3-4a5096a319bf","type":"paragraph","text":"Cung cấp thông tin về lĩnh vực, vấn đề cần giải quyết và hình thức hỗ trợ mong muốn. Trung tâm Đổi mới Sáng tạo Gia Lai sẽ tiếp nhận, làm rõ và đề xuất phương án kết nối phù hợp."},{"id":"6758a0bc-fecb-4a8c-ba62-4db93ad6651f","type":"heading","level":3,"text":"Kết nối đúng chuyên môn – Tháo gỡ đúng nút thắt"},{"id":"9b1c54f8-a48f-426b-81fe-077350dc41e3","type":"paragraph","text":"Gửi thông tin về bài toán hoặc nhu cầu hợp tác của đơn vị. Trung tâm Đổi mới Sáng tạo Gia Lai sẽ tiếp nhận, làm rõ yêu cầu và kết nối với chuyên gia hoặc đối tác phù hợp."},{"id":"e191e5c4-a188-4939-88d1-23e247656a72","type":"cta","label":"GỬI NHU CẦU CHUYÊN GIA","url":"/contact"},{"id":"ea9ed3a0-4a66-46a6-a8fa-8157309971c8","type":"cta","label":"TRAO ĐỔI VỚI TRUNG TÂM","url":"/contact"}]}'::jsonb, 'https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image114.png?tr=w-1200,q-80,f-auto', 'Kết nối chuyên gia và hệ sinh thái | VDCD Gia Lai', 'Kết nối đúng chuyên môn – Tháo gỡ đúng nút thắt – Mở rộng cơ hội hợp tác giữa chính quyền, doanh nghiệp, viện nghiên cứu và trường đại học.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'c0110001-0000-4000-a000-000000000003', 'program-thumb-ket-noi-chuyen-gia-va-he-sinh-thai'),
  ('a1b2c3d4-e5f6-4a7b-8c9d-012345678904', 'Tư vấn chuyển đổi số cấp tỉnh', 'tu-van-chuyen-doi-so-cap-tinh', 'Tư vấn chuyển đổi số từ bài toán thực tế đến lộ trình khả thi. Khảo sát hiện trạng, xây dựng danh mục ưu tiên và dashboard giám sát toàn diện cho địa phương.', '{"version":1,"blocks":[{"id":"37709751-8d48-4ee6-8410-a09f3c52b144","type":"heading","level":2,"text":"TƯ VẤN CHUYỂN ĐỔI SỐ"},{"id":"e15c1659-32ca-4d89-9ddc-da41518b3422","type":"paragraph","text":"Từ bài toán của từng đơn vị đến lộ trình chuyển đổi số toàn diện"},{"id":"bba20b79-d207-41e2-84d9-d152ed58c512","type":"paragraph","text":"Chuyển đổi số không đơn thuần là trang bị phần mềm, thiết bị hay đưa hồ sơ giấy lên máy tính. Giá trị thực sự chỉ được tạo ra khi công nghệ giúp cải tiến quy trình, kết nối dữ liệu và nâng cao hiệu quả quản lý, điều hành."},{"id":"bee64368-dd78-439d-99b6-8839afb8c1d5","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai kết nối chuyên gia và hệ sinh thái công nghệ để hỗ trợ tỉnh, các sở, ban, ngành, địa phương và doanh nghiệp đánh giá hiện trạng, xác định bài toán ưu tiên, xây dựng lộ trình và thử nghiệm giải pháp phù hợp."},{"id":"2092fd24-3cb2-4451-9147-c3f1cdb30b2a","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image4.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"DashBoard quản lí toàn bộ dự án thuộc Gia Lai","caption":"DashBoard quản lí toàn bộ dự án thuộc Gia Lai"},{"id":"df3c6b77-81e2-4b79-8d29-928c2ec57297","type":"heading","level":2,"text":"CHUYỂN ĐỔI SỐ NÊN BẮT ĐẦU TỪ ĐÂU?"},{"id":"94c52544-870a-4e90-ad92-46f4be3f42b6","type":"paragraph","text":"Nhiều đơn vị nhận thấy cần chuyển đổi số nhưng chưa xác định rõ nên triển khai khâu nào trước, lựa chọn công nghệ gì và đánh giá hiệu quả bằng cách nào."},{"id":"17b1ec96-41c0-4be5-ac2e-8c930c65064c","type":"paragraph","text":"Những điểm nghẽn thường gặp gồm:"},{"id":"e0ff021a-fa56-4cad-b4b5-f59755d84f97","type":"paragraph","text":"Quy trình còn phụ thuộc nhiều vào thao tác thủ công."},{"id":"173e2452-2b43-40e7-8c25-1f0bcb2098af","type":"paragraph","text":"Dữ liệu phân tán giữa hồ sơ, phần mềm và các phòng ban."},{"id":"4144de23-4acc-4cd4-b8d3-567dbf68d209","type":"paragraph","text":"Hệ thống hiện có chưa kết nối hoặc khó mở rộng."},{"id":"a3fd702a-cfe5-4452-907b-dd9f519eb715","type":"paragraph","text":"Việc tổng hợp báo cáo mất nhiều thời gian."},{"id":"e57692ce-7b66-4f75-9715-8042ae344557","type":"paragraph","text":"Khó theo dõi tiến độ và hoạt động theo thời gian thực."},{"id":"9b630deb-7174-4772-9a55-0788a6f15ad0","type":"paragraph","text":"Đã đầu tư công nghệ nhưng chưa khai thác hiệu quả."},{"id":"d2594eb3-3748-40d2-9d61-22530fafd5ca","type":"paragraph","text":"Nhân sự chưa sẵn sàng tiếp nhận quy trình và công cụ mới."},{"id":"afed32ec-da34-40dc-8136-93afc2735460","type":"paragraph","text":"Chưa có lộ trình và tiêu chí đánh giá rõ ràng."},{"id":"fb42b9b2-aa09-4ecc-bef9-43f7be9778ef","type":"paragraph","text":"Tư vấn chuyển đổi số giúp đơn vị trả lời ba câu hỏi quan trọng:"},{"id":"941ca75d-9c55-4745-9896-fcf494bfd89b","type":"paragraph","text":"Vấn đề nào cần giải quyết? Công nghệ nào phù hợp? Triển khai theo thứ tự nào để tạo ra hiệu quả?"},{"id":"29a7ba42-abdb-4343-b73f-1e4f23290e72","type":"heading","level":2,"text":"TƯ VẤN CHUYỂN ĐỔI SỐ CẤP TỈNH VÀ LIÊN NGÀNH"},{"id":"6b239ade-471b-4595-8db4-74d22f6d062b","type":"paragraph","text":"Chuyển đổi số cấp tỉnh không thể triển khai riêng lẻ tại từng cơ quan. Quy trình, dữ liệu và nhiệm vụ của các sở, ban, ngành có mối liên hệ chặt chẽ, đòi hỏi một lộ trình tổng thể nhưng vẫn phải phù hợp với đặc thù của từng lĩnh vực."},{"id":"9852b6cf-3c83-4c9e-8437-1d7f4b3b68b7","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai có khả năng phối hợp tư vấn:"},{"id":"fdc5a1d4-8139-4317-a5d7-b003b10d5d14","type":"paragraph","text":"Khảo sát hiện trạng chuyển đổi số tại các sở, ban, ngành."},{"id":"e41531a7-7ae2-41e2-be9a-519b3a42a427","type":"paragraph","text":"Tổng hợp nhu cầu và mức độ sẵn sàng của từng đơn vị."},{"id":"35cf69d8-0acd-4c5c-9bf8-93b5266e3a8a","type":"paragraph","text":"Rà soát quy trình, phần mềm và nguồn dữ liệu hiện có."},{"id":"2d66f1af-8160-447a-9abe-1065595934cd","type":"paragraph","text":"Xác định dữ liệu chuyên ngành và dữ liệu có thể chia sẻ."},{"id":"dc491f94-64cd-44a4-8106-b6c0aa485afd","type":"paragraph","text":"Xây dựng danh mục nhiệm vụ chuyển đổi số theo mức độ ưu tiên."},{"id":"f96ed4bd-00a4-496f-9801-32f76d0c2eee","type":"paragraph","text":"Đề xuất kiến trúc tích hợp và nền tảng dữ liệu dùng chung."},{"id":"224d1765-0578-407f-af57-ac8be0f848b4","type":"paragraph","text":"Xây dựng dashboard theo dõi tiến độ và hỗ trợ điều hành."},{"id":"dadddb9a-094a-42ae-80fc-9b0ad3ff3c96","type":"paragraph","text":"Lựa chọn mô hình thí điểm trước khi triển khai diện rộng."},{"id":"771149db-bf94-4c95-aafa-7b233c430257","type":"paragraph","text":"Đào tạo và chuyển giao cho đội ngũ vận hành tại địa phương."},{"id":"3549000d-4277-4d87-a4b1-caab8e255b45","type":"paragraph","text":"Phạm vi có thể bao gồm hành chính công, đất đai, tài nguyên và môi trường, xây dựng, đô thị, giao thông, nông nghiệp, lâm nghiệp, giáo dục, y tế, du lịch và quản lý hạ tầng."},{"id":"b98bf238-1e64-49e1-8dea-ccda506c792a","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image109.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Tham dự tư vấn chuyển đổi số tại UBND xã Tây Sơn","caption":"Tham dự tư vấn chuyển đổi số tại UBND xã Tây Sơn"},{"id":"6eeadb24-c1f3-468e-a63a-6187cbc3845a","type":"heading","level":2,"text":"NỘI DUNG TƯ VẤN"},{"id":"72a2f8ca-7266-4cd0-af23-9d1574b2d727","type":"paragraph","text":"Đánh giá hiện trạng và xác định ưu tiên"},{"id":"f53430f6-7966-45a8-a0ca-d84dd702c929","type":"paragraph","text":"Khảo sát quy trình, dữ liệu, phần mềm, thiết bị, hạ tầng và năng lực nhân sự. Qua đó xác định những điểm nghẽn cần giải quyết, khả năng kế thừa hệ thống hiện có và các nhiệm vụ nên triển khai trước."},{"id":"c090c150-d14e-4823-95b1-2ec84567f4d6","type":"paragraph","text":"Số hóa quy trình và quản trị dữ liệu"},{"id":"b30b0715-ad98-464e-a716-5a94a7e96f14","type":"paragraph","text":"Rà soát các bước xử lý công việc, giảm thao tác trùng lặp và đề xuất phương án số hóa phù hợp."},{"id":"3d12c1f7-2fcd-4e69-9775-03b56588b703","type":"paragraph","text":"Dữ liệu được định hướng thu thập, chuẩn hóa, phân quyền và khai thác thống nhất để phục vụ tra cứu, báo cáo và hỗ trợ ra quyết định."},{"id":"ca62cd1b-ea94-400c-989c-940c7df433d1","type":"paragraph","text":"Kiến trúc công nghệ và tích hợp hệ thống"},{"id":"38d2fab1-205e-4ba8-b209-d8c0f1a03f28","type":"paragraph","text":"Giải pháp được lựa chọn dựa trên bài toán và điều kiện vận hành, có thể kết hợp:"},{"id":"0d32e5fd-79fb-404f-99cb-31c0eb01cbb6","type":"paragraph","text":"UAV, GIS và dữ liệu không gian."},{"id":"867046f6-3951-46ab-a20f-5c47a0c80c2d","type":"paragraph","text":"AI và phân tích hình ảnh."},{"id":"eb93d4ce-483c-4137-bef5-f8641e8d51de","type":"paragraph","text":"Camera AI, cảm biến và IoT."},{"id":"e0dcc556-f52f-44ab-809d-0145b070ced3","type":"paragraph","text":"Phần mềm, dashboard và nền tảng quản lý."},{"id":"195bb345-95f7-4c98-bb72-dad360a511fb","type":"paragraph","text":"Trung tâm dữ liệu và hạ tầng tính toán."},{"id":"636a9ab8-38ab-41f1-b8ca-e10b7021c4f6","type":"paragraph","text":"Các hệ thống được định hướng kết nối, chia sẻ và hạn chế hình thành những kho dữ liệu riêng lẻ, khó khai thác."},{"id":"3e576893-d863-4e0d-878b-60d08ad7438f","type":"paragraph","text":"Thí điểm và mở rộng giải pháp"},{"id":"e54d3cde-81df-4b80-bd52-1dd40d2363f9","type":"paragraph","text":"Một quy trình, khu vực hoặc bài toán ưu tiên được lựa chọn để xây dựng mô hình thử nghiệm, POC hoặc chương trình thí điểm."},{"id":"2a0595bf-b135-48c8-9aa1-c54f6816763b","type":"paragraph","text":"Kết quả được đo lường và điều chỉnh trước khi mở rộng, giúp đơn vị kiểm soát chi phí, hạn chế rủi ro và đánh giá được hiệu quả thực tế."},{"id":"79017cc8-232f-4dae-89c8-84bb997c0358","type":"heading","level":2,"text":"QUY TRÌNH TƯ VẤN CHUYỂN ĐỔI SỐ"},{"id":"04c9d940-531a-45f3-9a6e-39c8cfee391c","type":"heading","level":3,"text":"01. Tiếp nhận nhu cầu"},{"id":"d3fab5b2-34ce-48a1-8f8d-1cad830bf3c6","type":"paragraph","text":"Trao đổi về hiện trạng, khó khăn, mục tiêu và phạm vi cần tư vấn."},{"id":"b78ad70a-5800-4a4e-8981-94c06ba79f73","type":"heading","level":3,"text":"02. Khảo sát và phân tích"},{"id":"acf0e053-2c27-42c6-860f-6da7debfe79a","type":"paragraph","text":"Đánh giá quy trình, dữ liệu, hệ thống, hạ tầng và nguồn lực liên quan."},{"id":"47cf358b-15cd-4ec7-bbe1-c793951a1ef5","type":"heading","level":3,"text":"03. Xây dựng danh mục ưu tiên"},{"id":"32d88b8c-a6a4-4c7c-8d73-9cc70b09557b","type":"paragraph","text":"Xác định những bài toán có tính cấp thiết, khả thi và khả năng tạo ra giá trị rõ ràng."},{"id":"12965165-c15d-4c68-a21a-3268ceea3ea1","type":"heading","level":3,"text":"04. Đề xuất lộ trình và giải pháp"},{"id":"cab03d3c-5b14-4c88-82f6-c15a8a45c0c2","type":"paragraph","text":"Xây dựng các giai đoạn triển khai, kiến trúc công nghệ, nguồn lực và tiêu chí đánh giá."},{"id":"9d00d03f-3592-4618-b7ba-8f8041f33edb","type":"heading","level":3,"text":"05. Thí điểm, đánh giá và mở rộng"},{"id":"a8c53f1f-634e-41c4-a10c-151e271df3c1","type":"paragraph","text":"Thử nghiệm trong phạm vi phù hợp, đo lường kết quả, điều chỉnh và đề xuất kế hoạch nhân rộng."},{"id":"dc0d8151-269e-43ed-a576-fd18e74cf52b","type":"heading","level":2,"text":"SẢN PHẨM TƯ VẤN"},{"id":"555a5b23-bf52-4f99-8b79-7a23a86beb42","type":"paragraph","text":"Tùy theo phạm vi, sản phẩm có thể bao gồm:"},{"id":"3e5b364d-d28c-43d2-8908-72797e7bb1b5","type":"paragraph","text":"Báo cáo khảo sát và đánh giá hiện trạng."},{"id":"2b1187d6-fc2a-4bc0-b885-06aadf1d93b5","type":"paragraph","text":"Sơ đồ quy trình và các điểm nghẽn cần cải tiến."},{"id":"d92469ce-237c-4673-a79d-ba6238d330be","type":"paragraph","text":"Danh mục nhiệm vụ chuyển đổi số ưu tiên."},{"id":"5cde926e-08d8-498f-a3ea-4e2be009e655","type":"paragraph","text":"Danh mục dữ liệu chuyên ngành và dữ liệu dùng chung."},{"id":"434820cb-9b6a-43a3-83f9-ae27fe730e80","type":"paragraph","text":"Đề xuất kiến trúc công nghệ và phương án tích hợp."},{"id":"8dc33b72-f8dd-4b86-9a33-f944242e9a46","type":"paragraph","text":"Lộ trình triển khai theo từng giai đoạn."},{"id":"c55ee326-1bf3-4b4c-b167-7b88afebbba1","type":"paragraph","text":"Kế hoạch thí điểm hoặc mô hình POC."},{"id":"ae242d8b-e43f-46d4-8734-d4dee55edd22","type":"paragraph","text":"Dashboard theo dõi tiến độ và kết quả."},{"id":"f72b4ca6-38c0-47ec-8423-bac78c09c64f","type":"paragraph","text":"Bộ chỉ số đánh giá hiệu quả."},{"id":"34826b17-a118-4cb7-9b6f-c8fba3b7ac88","type":"paragraph","text":"Kế hoạch đào tạo, chuyển giao và vận hành."},{"id":"f65953b6-c956-4f39-bf60-049bfa7e83a7","type":"paragraph","text":"Sản phẩm tư vấn cần giúp đơn vị biết rõ việc gì cần làm trước, nguồn lực nào cần chuẩn bị và hiệu quả được đánh giá ra sao."},{"id":"c5f001cc-46d9-4365-ab7a-75aacfa13c8c","type":"heading","level":2,"text":"NĂNG LỰC KẾT NỐI GIẢI PHÁP"},{"id":"bbf1c63a-090a-4c6a-8076-4e58065a54e5","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai kết nối nguồn lực trong hệ sinh thái VDCD Group:"},{"id":"8a776e1d-3e8c-4773-a11c-82a62a0cdbec","type":"paragraph","text":"Mạng lưới chuyên gia và đội ngũ kỹ thuật đa lĩnh vực."},{"id":"078d689f-94b0-4bda-be62-445d51f8aa5b","type":"paragraph","text":"Năng lực khảo sát và thu thập dữ liệu hiện trường."},{"id":"ac5e634c-5f5a-4f40-afa7-f8bb48218da3","type":"paragraph","text":"Công nghệ UAV, AI, GIS, IoT và mô hình 3D."},{"id":"50244fde-2d1d-440e-86f5-9a41f3107d59","type":"paragraph","text":"Phần mềm, dashboard và nền tảng quản lý."},{"id":"8a74db5d-0c27-4f58-915e-575f5773b6a2","type":"paragraph","text":"Hạ tầng trung tâm dữ liệu và tính toán."},{"id":"18b0be33-6e74-4ca9-8a64-974e8bfd7c85","type":"paragraph","text":"Khả năng thử nghiệm, tích hợp và chuyển giao giải pháp."},{"id":"abe0d0f3-d3d7-43e0-a1a2-f16969c68750","type":"paragraph","text":"Trung tâm tiếp cận theo nguyên tắc bài toán đi trước công nghệ, kế thừa hệ thống hiện có, triển khai theo từng giai đoạn và hướng đến khả năng vận hành lâu dài."},{"id":"ee1d3d6f-0284-4795-b1eb-e034206b7d13","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image111.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"Chủ tịch HĐQT VDCD Group đại diện đề xuất các công nghệ chuyển đổi số","caption":"Chủ tịch HĐQT VDCD Group đại diện đề xuất các công nghệ chuyển đổi số"},{"id":"abc1a31f-7ea1-472c-8ade-c0be4039846e","type":"heading","level":2,"text":"BẮT ĐẦU TỪ MỘT BÀI TOÁN CỤ THỂ"},{"id":"44e6b04e-9e02-49d3-8654-c53eee983c48","type":"paragraph","text":"Không có một mô hình chuyển đổi số duy nhất phù hợp với mọi tổ chức. Một lộ trình hiệu quả phải phản ánh đúng hiện trạng, giải quyết đúng nhu cầu và phù hợp với nguồn lực triển khai."},{"id":"c83dfb73-5092-4e5e-bbd7-1135a2623dba","type":"heading","level":2,"text":"ĐĂNG KÝ KHẢO SÁT NHU CẦU CHUYỂN ĐỔI SỐ"},{"id":"2a557942-d800-448c-a190-a14fe84a5b49","type":"paragraph","text":"Gửi thông tin về hiện trạng, vấn đề cần giải quyết và mục tiêu dự kiến. Trung tâm Đổi mới Sáng tạo Gia Lai sẽ tiếp nhận, trao đổi và đề xuất phương án khảo sát phù hợp."},{"id":"740fc6bd-a60d-4f6e-afd6-3f417fb52540","type":"heading","level":3,"text":"Bắt đầu từ một bài toán cụ thể"},{"id":"e5532f1e-db0e-4976-89fb-bf0bf7c48c81","type":"paragraph","text":"Gửi thông tin về hiện trạng, vấn đề cần giải quyết và mục tiêu dự kiến. Trung tâm Đổi mới Sáng tạo Gia Lai sẽ tiếp nhận, trao đổi và đề xuất phương án khảo sát phù hợp."},{"id":"acdd0c04-5e2c-48ff-a08c-e1256f2f9a97","type":"cta","label":"ĐĂNG KÝ KHẢO SÁT","url":"/contact"},{"id":"ef307d43-8644-427d-b8cc-e3eeb61e5932","type":"cta","label":"TRAO ĐỔI VỚI TRUNG TÂM","url":"/contact"}]}'::jsonb, 'https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image4.png?tr=w-1200,q-80,f-auto', 'Tư vấn chuyển đổi số cấp tỉnh | VDCD Gia Lai', 'Tư vấn chuyển đổi số từ bài toán thực tế đến lộ trình khả thi. Khảo sát hiện trạng, xây dựng danh mục ưu tiên và dashboard giám sát toàn diện cho địa phương.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'c0110001-0000-4000-a000-000000000004', 'program-thumb-tu-van-chuyen-doi-so-cap-tinh'),
  ('a1b2c3d4-e5f6-4a7b-8c9d-012345678905', 'Hội thảo, sự kiện đổi mới sáng tạo', 'hoi-thao-su-kien', 'Diễn đàn chia sẻ tri thức công nghệ, kết nối mạng lưới doanh nghiệp, nhà khoa học và xúc tiến các chương trình đổi mới sáng tạo toàn diện.', '{"version":1,"blocks":[{"id":"f96e4b9f-c2ff-4093-b68f-6024ab86eabf","type":"paragraph","text":"Keyword chính: hệ sinh thái khởi nghiệp sáng tạo Gia Lai"},{"id":"87c89883-d4ef-4406-af8d-114a555680bb","type":"paragraph","text":"Keyword phụ: Trung tâm Đổi mới Sáng tạo Gia Lai, khởi nghiệp sáng tạo Gia Lai, liên kết 3 nhà, chuyển đổi số Gia Lai, đổi mới sáng tạo, hỗ trợ startup, khoa học công nghệ Gia Lai."},{"id":"56d5c3ed-9ca3-42ba-9a5d-41ab88b5021a","type":"paragraph","text":"Kết nối “3 nhà” - Xây dựng hệ sinh thái khởi nghiệp sáng tạo Gia Lai từ những bài toán thực tế"},{"id":"616680a0-1f60-4f40-91e1-ff0b6241a2ab","type":"paragraph","text":"Ngày 18/05/2026, Hội thảo truyền thông chính sách về khởi nghiệp sáng tạo được tổ chức tại Gia Lai, tạo không gian kết nối giữa cơ quan quản lý, trường đại học, doanh nghiệp và cộng đồng khởi nghiệp. Trong đó, mô hình liên kết “3 nhà” - Nhà nước, Nhà trường và Doanh nghiệp - được xác định là một trong những nền tảng quan trọng để đưa công nghệ, tri thức và nguồn lực đến gần hơn với những bài toán thực tế của thị trường."},{"id":"d29fc91a-485d-45fb-89fd-4af0daa3c49c","type":"paragraph","text":"Đối với Trung tâm Đổi mới Sáng tạo Gia Lai (VDCD Gia Lai), một hệ sinh thái đổi mới sáng tạo chỉ thực sự vận hành khi các thành phần bên trong có khả năng kết nối và bổ trợ cho nhau."},{"id":"b3a7fd7b-b9ce-4266-8502-10f72b30ab65","type":"paragraph","text":"Nhà nước tạo hành lang và môi trường phát triển. Nhà trường cung cấp tri thức, nghiên cứu và nguồn nhân lực. Doanh nghiệp đưa ra bài toán, thị trường và trực tiếp chuyển hóa công nghệ thành sản phẩm, dịch vụ."},{"id":"54705776-5f31-4fd7-8d8e-91d85b13ff0f","type":"paragraph","text":"Khi ba nguồn lực này cùng vận hành trong một hệ thống, đổi mới sáng tạo có thể đi xa hơn các hoạt động phong trào để tiến tới những kết quả cụ thể: ý tưởng được thử nghiệm, công nghệ được ứng dụng và doanh nghiệp tạo ra giá trị mới."},{"id":"3ddea457-c453-483f-be97-00ecaa0e3c18","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image80.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"VDCD Gia Lai","caption":null},{"id":"ebc0368d-77e4-4742-8a04-95794ddeaff9","type":"paragraph","text":"Hội thảo tạo không gian kết nối giữa cơ quan quản lý, trường đại học, doanh nghiệp và cộng đồng khởi nghiệp sáng tạo tại Gia Lai."},{"id":"183e8da1-ca69-4fbd-9f17-29aa8a08b23f","type":"paragraph","text":"Từ hỗ trợ khởi nghiệp đến kiến tạo hệ sinh thái"},{"id":"62603515-12bb-4225-b181-e1a8353bb9b5","type":"paragraph","text":"Sự phát triển của một startup không chỉ phụ thuộc vào chất lượng ý tưởng."},{"id":"ec2a3d6e-283f-4335-b637-9c291c6d24f5","type":"paragraph","text":"Một dự án có thể sở hữu giải pháp tốt nhưng vẫn gặp khó khăn khi thiếu dữ liệu, công nghệ, chuyên gia, thị trường hoặc nguồn lực để kiểm chứng mô hình. Đây cũng là những điểm nghẽn thường xuất hiện trong quá trình phát triển của doanh nghiệp đổi mới sáng tạo."},{"id":"ddaaacec-845b-44c4-af5f-cfa9773f6774","type":"paragraph","text":"Vì vậy, xây dựng hệ sinh thái không đơn thuần là gia tăng số lượng chương trình hỗ trợ mà cần tạo ra mạng lưới có khả năng đưa đúng nguồn lực đến đúng dự án vào đúng thời điểm."},{"id":"d4d760b7-92b6-48e8-9ee6-c94d9adf8f19","type":"paragraph","text":"Tại hội thảo, những vấn đề về tiếp cận công nghệ, thị trường, cơ chế hỗ trợ và mức độ liên kết giữa các chủ thể trong hệ sinh thái đã được đặt ra. Đồng thời, tư duy hỗ trợ doanh nghiệp cũng được mở rộng theo hướng chủ động kiến tạo môi trường để đổi mới sáng tạo phát triển."},{"id":"c4c5f1c4-bbc7-4d0a-b506-cbbbfa87011f","type":"paragraph","text":"Với cách tiếp cận đó, startup không phải chủ thể duy nhất của hệ sinh thái. Các cơ quan quản lý, trường đại học, doanh nghiệp công nghệ, chuyên gia và nhà đầu tư đều trở thành những mắt xích trong cùng một chuỗi giá trị."},{"id":"b7d359d5-f202-47c3-b900-8445f51f77d2","type":"paragraph","text":"Phát biểu khai mạc hội thảo, ông Trần Kim Kha - Giám đốc Sở Khoa học và Công nghệ tỉnh Gia Lai nhấn mạnh: Khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số đang trở thành động lực quan trọng thúc đẩy phát triển kinh tế - xã hội nhanh và bền vững. Nghị quyết số 57-NQ/TW của Bộ Chính trị đã xác định phát triển khoa học, công nghệ, đổi mới sáng tạo và chuyển đổi số là “đột phá quan trọng hàng đầu”, góp phần nâng cao năng lực cạnh tranh quốc gia."},{"id":"af0c2775-f931-40f8-8318-5c6534a49e3d","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image34.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"VDCD Gia Lai","caption":null},{"id":"e70a476c-3625-488e-a641-a9444500ff31","type":"paragraph","text":"Ông Trần Kim Kha - Giám đốc Sở KH&CN phát biểu khai mạc hội thảo."},{"id":"c932ec8d-6480-466f-9f96-7df78495e823","type":"paragraph","text":"VDCD Gia Lai - Kết nối bài toán với giải pháp"},{"id":"55c00dd5-623c-4a58-ae81-5d2966ad870b","type":"paragraph","text":"Tại chương trình, Trung tâm Đổi mới Sáng tạo Gia Lai giới thiệu mô hình trung tâm đổi mới sáng tạo do doanh nghiệp làm chủ, với định hướng tập trung vào khả năng triển khai và nhu cầu thực tế của thị trường."},{"id":"326af8ed-d1dc-4e05-a53e-794a4323e5b9","type":"paragraph","text":"Thay vì bắt đầu bằng câu hỏi “công nghệ nào đang là xu hướng?”, cách tiếp cận của Trung tâm hướng đến câu hỏi quan trọng hơn: Doanh nghiệp đang gặp vấn đề gì và công nghệ có thể giải quyết vấn đề đó như thế nào?"},{"id":"d8feaaf3-33e5-4c19-aa0d-e3061cbb8025","type":"paragraph","text":"Từ bài toán cụ thể, Trung tâm có thể kết nối doanh nghiệp với đơn vị công nghệ, chuyên gia, trường đại học hoặc các nguồn lực phù hợp để phát triển giải pháp."},{"id":"e090f55a-08d5-4673-9931-e7ad1ec1e2c3","type":"paragraph","text":"Mô hình này tạo thành một pipeline tương đối rõ ràng:"},{"id":"5e0a7581-a6f0-4654-aa2c-2c3aab6eb6b4","type":"paragraph","text":"Bài toán → Giải pháp → Thử nghiệm → Đánh giá → Triển khai → Mở rộng."},{"id":"fb761006-7cd8-409a-aaf8-19aa60178afa","type":"paragraph","text":"Công nghệ vì vậy không phải đích đến cuối cùng. Giá trị nằm ở việc công nghệ có thể giúp doanh nghiệp tối ưu vận hành, nâng cao năng suất, phát triển sản phẩm mới hay tạo ra lợi thế cạnh tranh như thế nào."},{"id":"aba29387-6e47-49f5-a8fc-8637189781a8","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image104.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"VDCD Gia Lai","caption":null},{"id":"16375d5d-73d6-4754-af31-1b2ce0f7f4bb","type":"paragraph","text":"Đại diện Công ty Cổ phần Trung tâm Đổi mới sáng tạo Gia Lai (VDCD Gia Lai) giới thiệu mô hình trung tâm đổi mới sáng tạo do doanh nghiệp làm chủ."},{"id":"c27372c1-60de-4371-8698-f09e3456d769","type":"paragraph","text":"Công nghệ và chuyển đổi số phải tạo ra giá trị đo lường được"},{"id":"548d8d80-eab7-4cf4-ba89-d10d435954fb","type":"paragraph","text":"Một nội dung quan trọng khác tại chương trình là khả năng ứng dụng khoa học – công nghệ và chuyển đổi số vào hoạt động của doanh nghiệp. Các vấn đề từ truy xuất nguồn gốc, quản trị dữ liệu đến các giải pháp chuyển đổi số được đặt trong bối cảnh thực tế thay vì tiếp cận công nghệ như một xu hướng độc lập."},{"id":"7b9bdda4-a800-40ac-af4a-3573fa819818","type":"paragraph","text":"Đây cũng là nguyên tắc quan trọng khi triển khai chuyển đổi số. Một hệ thống mới chỉ thực sự có giá trị khi nó giải quyết được một điểm nghẽn. Một nền tảng dữ liệu chỉ có ý nghĩa khi dữ liệu có thể hỗ trợ quá trình vận hành và ra quyết định. Một giải pháp tự động hóa chỉ hiệu quả khi giúp giảm thao tác, thời gian hoặc chi phí."},{"id":"216b8ab0-6eef-485d-9021-0e825ef2a903","type":"paragraph","text":"Do đó, hiệu quả của đổi mới sáng tạo cần được đánh giá thông qua outcome – kết quả mà doanh nghiệp và người dùng thực sự nhận được – thay vì chỉ dựa trên số lượng công nghệ được triển khai."},{"id":"d1dad8b7-55ef-46f2-84df-d768d32e4137","type":"paragraph","text":"Liên kết “3 nhà” để rút ngắn khoảng cách từ nghiên cứu đến thị trường"},{"id":"282aa7cb-9e25-4cc9-acdd-1b89e15458b1","type":"paragraph","text":"Hội thảo cũng đánh dấu nhiều hoạt động ký kết hợp tác giữa các thành phần của hệ sinh thái. Trong đó có thỏa thuận giữa Sở Khoa học và Công nghệ Gia Lai và Trung tâm Đổi mới Sáng tạo Gia Lai, giữa Sở Khoa học và Công nghệ với Trường Đại học FPT tại Quy Nhơn, cùng thỏa thuận hợp tác giữa VDCD Gia Lai và Trường Đại học Quy Nhơn."},{"id":"f53c0219-bd80-47aa-ab94-ad729b01c5bf","type":"paragraph","text":"Các kết nối này tạo nền tảng cho một mô hình hợp tác rộng hơn giữa chính sách nghiên cứu  đào tạo công nghệ doanh nghiệp thị trường."},{"id":"de8e07d8-2a44-4d9a-9668-3846cfde859c","type":"paragraph","text":"Đặc biệt, sự tham gia của các trường đại học giúp mở rộng nguồn lực nghiên cứu và nguồn nhân lực trẻ cho hệ sinh thái. Những kết quả nghiên cứu tiềm năng có thêm cơ hội tiếp cận bài toán của doanh nghiệp, được thử nghiệm trong môi trường thực tế và tiến gần hơn đến khả năng thương mại hóa."},{"id":"ca2e4e58-ca41-4f8c-9cd0-e61f4d920e5a","type":"paragraph","text":"Ở chiều ngược lại, doanh nghiệp có thể đưa nhu cầu thực tế trở lại môi trường đào tạo và nghiên cứu, giúp rút ngắn khoảng cách giữa kiến thức, công nghệ và yêu cầu của thị trường."},{"id":"01622845-3e2e-421b-9f9a-6c5b399b5b95","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image12.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"VDCD Gia Lai","caption":null},{"id":"cbaeee70-559f-404d-beac-526aafcfa781","type":"paragraph","text":"Đại diện Sở KH&CN Gia Lai và Công ty Cổ phần Trung tâm Đổi mới sáng tạo Gia Lai (VDCD Gia Lai) ký kết thỏa thuận hợp tác phát triển hệ sinh thái khởi nghiệp sáng tạo."},{"id":"1917d935-2f36-4645-8749-9d63d4a3ada8","type":"paragraph","text":"Đồng hành cùng 30 doanh nghiệp và 10 dự án khởi nghiệp sáng tạo"},{"id":"0e8ba66d-fe21-4f0d-b14a-ce53839ba93b","type":"paragraph","text":"Một trong những mục tiêu cụ thể được VDCD Gia Lai đặt ra tại chương trình là kết nối và đồng hành cùng 30 doanh nghiệp cùng 10 nhóm, cá nhân khởi nghiệp sáng tạo trong quá trình phát triển sản phẩm, hoàn thiện ý tưởng và mở rộng khả năng kết nối với hệ sinh thái. Đây là bước chuyển từ xây dựng mạng lưới sang triển khai trên những đối tượng cụ thể."},{"id":"b5552875-4fc9-484a-8c04-94f033388052","type":"paragraph","text":"Tùy theo giai đoạn phát triển, mỗi dự án sẽ có nhu cầu khác nhau: hoàn thiện sản phẩm, tiếp cận công nghệ, tìm kiếm chuyên gia, kiểm chứng thị trường, xây dựng mô hình kinh doanh hoặc kết nối với các nguồn lực tiếp theo. Vai trò của hệ sinh thái là giúp những nhu cầu đó tìm được đúng điểm kết nối."},{"id":"8b6d5710-6cf0-4765-ba79-51eea9ed6104","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image72.png?tr=w-1200,q-80,f-auto","fileId":null,"mediaId":null,"alt":"VDCD Gia Lai","caption":null},{"id":"a8ae6cd7-dc77-49c4-8de0-74c48408848a","type":"paragraph","text":"Đại diện VDCD Gia Lai trao cam kết hỗ trợ cho các doanh nghiệp, dự án khởi nghiệp sáng tạo trên địa bàn tỉnh."},{"id":"c52201a5-dc52-418f-8097-c858ef91dde7","type":"paragraph","text":"Một hệ sinh thái được đo bằng kết quả"},{"id":"d99a7c52-01bf-400e-8642-02a4d7036b81","type":"paragraph","text":"Đối với Trung tâm Đổi mới Sáng tạo Gia Lai, số lượng sự kiện hay kết nối không phải thước đo cuối cùng của một hệ sinh thái đổi mới sáng tạo."},{"id":"b406c46a-49ac-4cef-be18-c372c1b16c04","type":"paragraph","text":"Điều quan trọng hơn là sau những kết nối đó, bao nhiêu bài toán tìm được giải pháp, bao nhiêu ý tưởng bước vào giai đoạn thử nghiệm, bao nhiêu công nghệ được ứng dụng và bao nhiêu doanh nghiệp tạo ra giá trị mới."},{"id":"6b0d3fdf-3a42-4383-b65a-0b207febdeed","type":"paragraph","text":"Mô hình liên kết “3 nhà” vì vậy không chỉ là một cấu trúc hợp tác. Đây là cách tạo ra một vòng tuần hoàn nguồn lực: chính sách mở đường cho đổi mới; trường đại học cung cấp tri thức và con người; doanh nghiệp đưa công nghệ vào thị trường; còn kết quả từ thị trường tiếp tục tạo ra những bài toán mới cho nghiên cứu và đổi mới."},{"id":"76d28e85-b18d-4df4-81fc-39bd92f68b9b","type":"paragraph","text":"Thông qua việc mở rộng mạng lưới hợp tác và triển khai các chương trình hỗ trợ cụ thể, Trung tâm Đổi mới Sáng tạo Gia Lai hướng đến xây dựng một hệ sinh thái nơi ý tưởng có không gian để thử nghiệm, doanh nghiệp có công nghệ để tăng trưởng và những kết nối có thể chuyển hóa thành giá trị thực tế cho địa phương."},{"id":"30ff37ad-ad23-43fc-a2c8-be4dcc65112e","type":"paragraph","text":"Hội nghị Xúc tiến đầu tư"},{"id":"18878780-f25d-4902-94e9-fa5ccfe298b4","type":"paragraph","text":"Từ khóa chính: Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026"},{"id":"92dcfcaa-4c30-428d-8b1f-1b7486b9f56a","type":"heading","level":3,"text":"Diễn đàn kết nối hệ sinh thái số Gia Lai"},{"id":"86bacd7c-c018-44c1-be4e-b7879557e88a","type":"paragraph","text":"Đăng ký tham dự các chương trình hội thảo, diễn đàn chuyển đổi số và sự kiện đổi mới sáng tạo để mở rộng mạng lưới hợp tác."},{"id":"481d78c3-9022-4335-9dd3-dd628b17b16b","type":"cta","label":"ĐĂNG KÝ THAM GIA","url":"/contact"},{"id":"9c41adc8-0559-4280-8fc0-86e002707963","type":"cta","label":"TRAO ĐỔI VỚI TRUNG TÂM","url":"/contact"}]}'::jsonb, 'https://ik.imagekit.io/po0s6zxoj/vdcd/solutions/doc_images/solution_image101.png?tr=w-1200,q-80,f-auto', 'Hội thảo, sự kiện đổi mới sáng tạo | VDCD Gia Lai', 'Diễn đàn chia sẻ tri thức công nghệ, kết nối mạng lưới doanh nghiệp, nhà khoa học và xúc tiến các chương trình đổi mới sáng tạo toàn diện.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'c0110001-0000-4000-a000-000000000005', 'program-thumb-hoi-thao-su-kien');

