INSERT INTO "solution" ("id", "title", "slug", "short_description", "content", "thumbnail", "meta_title", "meta_description", "is_published", "created_at", "updated_at", "field_id", "thumbnail_file_id", "website_url") VALUES
  
  ('9446a120-855a-4f3c-a028-e3948cfe74b5', 'Trung tâm Bản đồ số', 'trung-tam-ban-do-so', 'Cung cấp các dịch vụ bay quét 3D, trắc địa số hóa và thành lập bản đồ địa hình độ chính xác cao bằng máy bay không người lái.', '{"version":1,"blocks":[{"id":"af94aef6-199f-4888-92f7-719dcd83fb73","type":"paragraph","text":"Cung cấp các dịch vụ bay quét 3D, trắc địa số hóa và thành lập bản đồ địa hình độ chính xác cao bằng máy bay không người lái."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2024/03/5-768x431.jpg', 'Trung tâm Bản đồ số | VDCD', 'Cung cấp các dịch vụ bay quét 3D, trắc địa số hóa và thành lập bản đồ địa hình độ chính xác cao bằng máy bay không người lái.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'e20f8cfa-92dd-4302-a746-fe50562e19b4', 'solution-thumb-trung-tam-ban-do-so', 'https://vietflycam.vn/dich-vu/bay-quet-3d-trac-dia-so-va-thanh-lap-ban-do'),
  ('72d9f19f-af32-4233-afe6-4d5e74d91a14', 'Viện Thiết Kế Số', 'vien-thiet-ke-so', 'Nghiên cứu, phát triển ứng dụng mô hình thông tin công trình (BIM) và các giải pháp thiết kế số trong lĩnh vực xây dựng, kiến trúc.', '{"version":1,"blocks":[{"id":"e04a6a9e-7cc2-46ff-a4a5-b76b7c8bac2b","type":"paragraph","text":"Nghiên cứu, phát triển ứng dụng mô hình thông tin công trình (BIM) và các giải pháp thiết kế số trong lĩnh vực xây dựng, kiến trúc."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2024/03/picture1_8463e044ab0c465da2d031f6af1a4c5f_master-768x768.png', 'Viện Thiết Kế Số | VDCD', 'Nghiên cứu, phát triển ứng dụng mô hình thông tin công trình (BIM) và các giải pháp thiết kế số trong lĩnh vực xây dựng, kiến trúc.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-vien-thiet-ke-so', 'https://bimv.vn/'),
  ('8601ae3f-e0e3-45c5-ba1c-e7de47b20abd', 'Trung Tâm Giám Sát Số', 'trung-tam-giam-sat-so', 'Cung cấp hệ thống Auto Timelapse giám sát thông minh tiến độ xây dựng công trình, nông nghiệp và môi trường một cách tự động, trực quan.', '{"version":1,"blocks":[{"id":"b463cbb5-f1ee-43b9-bc35-d340a868621c","type":"paragraph","text":"Cung cấp hệ thống Auto Timelapse giám sát thông minh tiến độ xây dựng công trình, nông nghiệp và môi trường một cách tự động, trực quan."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2024/03/3123-768x512.jpg', 'Trung Tâm Giám Sát Số | VDCD', 'Cung cấp hệ thống Auto Timelapse giám sát thông minh tiến độ xây dựng công trình, nông nghiệp và môi trường một cách tự động, trực quan.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-trung-tam-giam-sat-so', 'https://autotimelapse.com'),
  ('c159272a-0884-4e1a-b664-5f8e0ad78054', 'Trung tâm dữ liệu siêu máy tính và đào tạo AI', 'trung-tam-du-lieu-sieu-may-tinh-va-dao-tao-ai', 'Xây dựng hạ tầng tính toán hiệu năng cao (HPC) và tổ chức các chương trình đào tạo trí tuệ nhân tạo chuyên sâu phục vụ chuyển đổi số doanh nghiệp.', '{"version":1,"blocks":[{"id":"9c84fd0a-8fe0-4aaf-b707-bc61c1674eb4","type":"paragraph","text":"Xây dựng hạ tầng tính toán hiệu năng cao (HPC) và tổ chức các chương trình đào tạo trí tuệ nhân tạo chuyên sâu phục vụ chuyển đổi số doanh nghiệp."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2025/10/z7173282299491_651f9e392555944f94acd55dab050480-768x576.jpg', 'Trung tâm dữ liệu siêu máy tính và đào tạo AI | VDCD', 'Xây dựng hạ tầng tính toán hiệu năng cao (HPC) và tổ chức các chương trình đào tạo trí tuệ nhân tạo chuyên sâu phục vụ chuyển đổi số doanh nghiệp.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'e1760c66-386b-4de3-8490-5d71680649cf', 'solution-thumb-trung-tam-du-lieu-sieu-may-tinh-va-dao-tao-ai', 'https://vdcd.vn/services/trung-tam-du-lieu-sieu-may-tinh-va-dao-tao-ai/'),
  ('2626ca50-c83c-4712-b055-620cf5996f33', 'Viện Nghiên cứu công nghệ không gian và dưới nước', 'vien-nghien-cuu-cong-nghe-khong-gian-va-duoi-nuoc', 'Nghiên cứu và ứng dụng các công nghệ tiên tiến trong không gian vũ trụ và thám hiểm, đo đạc môi trường dưới nước.', '{"version":1,"blocks":[{"id":"3ff4d625-6c17-4dd6-be4c-d72c6b84422b","type":"paragraph","text":"Nghiên cứu và ứng dụng các công nghệ tiên tiến trong không gian vũ trụ và thám hiểm, đo đạc môi trường dưới nước."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2025/10/Vien-khong-gian-va-duoi-nuoc-BK-768x499.jpg', 'Viện Nghiên cứu công nghệ không gian và dưới nước | VDCD', 'Nghiên cứu và ứng dụng các công nghệ tiên tiến trong không gian vũ trụ và thám hiểm, đo đạc môi trường dưới nước.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'e1760c66-386b-4de3-8490-5d71680649cf', 'solution-thumb-vien-nghien-cuu-cong-nghe-khong-gian-va-duoi-nuoc', 'https://iig.vn'),
  ('4b124ed2-25ae-4e1d-b408-538f470043ec', 'Trung tâm phần mềm VDCD – Soft', 'trung-tam-phan-mem-vdcd-soft', 'Phát triển các phần mềm quản lý doanh nghiệp, giải pháp chuyển đổi số chuyên sâu phục vụ hệ sinh thái kinh tế vùng và cả nước.', '{"version":1,"blocks":[{"id":"e4a5dac6-bb74-4b8d-a337-5f9c5b157e25","type":"paragraph","text":"Phát triển các phần mềm quản lý doanh nghiệp, giải pháp chuyển đổi số chuyên sâu phục vụ hệ sinh thái kinh tế vùng và cả nước."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2024/03/Untitled-1-01-1-768x768.png', 'Trung tâm phần mềm VDCD – Soft | VDCD', 'Phát triển các phần mềm quản lý doanh nghiệp, giải pháp chuyển đổi số chuyên sâu phục vụ hệ sinh thái kinh tế vùng và cả nước.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-trung-tam-phan-mem-vdcd-soft', 'https://geneat.vn'),
  ('f9ba2c8b-6f6b-4f4c-b259-f1c718e3544b', 'Trung Tâm Đổi Mới Sáng Tạo Tỉnh', 'trung-tam-doi-moi-sang-tao-tinh', 'Hỗ trợ ươm tạo khởi nghiệp, phát triển ý tưởng sáng tạo và thúc đẩy chuyển giao công nghệ tại địa phương.', '{"version":1,"blocks":[{"id":"e639e10c-9132-444c-9a58-cd1032c94368","type":"paragraph","text":"Hỗ trợ ươm tạo khởi nghiệp, phát triển ý tưởng sáng tạo và thúc đẩy chuyển giao công nghệ tại địa phương."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2025/11/S3-1-1-768x590.jpg', 'Trung Tâm Đổi Mới Sáng Tạo Tỉnh | VDCD', 'Hỗ trợ ươm tạo khởi nghiệp, phát triển ý tưởng sáng tạo và thúc đẩy chuyển giao công nghệ tại địa phương.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-trung-tam-doi-moi-sang-tao-tinh', 'https://vdcd.vn/services/trung-tam-doi-moi-sang-tao-tinh/'),
  ('5ebe0e7b-1b5f-44a1-bd8a-d874625e2c7b', 'Trung Tâm Chuyển giao Công Nghệ', 'trung-tam-chuyen-giao-cong-nghe', 'Cầu nối chuyển giao các công nghệ tiên tiến từ viện nghiên cứu, trường đại học đến các doanh nghiệp địa phương ứng dụng thực tiễn.', '{"version":1,"blocks":[{"id":"c723313b-4277-40fa-bd22-21581fc44e58","type":"paragraph","text":"Cầu nối chuyển giao các công nghệ tiên tiến từ viện nghiên cứu, trường đại học đến các doanh nghiệp địa phương ứng dụng thực tiễn."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2025/10/BOT06612-768x512.jpg', 'Trung Tâm Chuyển giao Công Nghệ | VDCD', 'Cầu nối chuyển giao các công nghệ tiên tiến từ viện nghiên cứu, trường đại học đến các doanh nghiệp địa phương ứng dụng thực tiễn.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-trung-tam-chuyen-giao-cong-nghe', 'https://vdcd.vn/services/trung-tam-chuyen-giao-cong-nghe/'),
  ('b7558158-7043-488f-b189-51bc1728035a', 'Máy Bay Việt', 'may-bay-viet', 'Đơn vị cung cấp giải pháp máy bay không người lái phục vụ nông nghiệp thông minh, khảo sát công nghiệp và quay chụp chuyên nghiệp.', '{"version":1,"blocks":[{"id":"e8c1d41c-5a48-4cc4-8ccf-a05f992f15ca","type":"paragraph","text":"Đơn vị cung cấp giải pháp máy bay không người lái phục vụ nông nghiệp thông minh, khảo sát công nghiệp và quay chụp chuyên nghiệp."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2025/10/1WUpukaXKpD5fkPMSNblWMSh6WCwXJ6Jj6f9AaF0YHj7OHjPJMzUbLBU1IEVPY2B2vQ-768x432.jpg', 'Máy Bay Việt | VDCD', 'Đơn vị cung cấp giải pháp máy bay không người lái phục vụ nông nghiệp thông minh, khảo sát công nghiệp và quay chụp chuyên nghiệp.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'e20f8cfa-92dd-4302-a746-fe50562e19b4', 'solution-thumb-may-bay-viet', 'https://maybayviet.com'),
  ('b6b431e4-4ea6-4908-a38d-ad45e8e00df9', 'Trung tâm phát triển Robot & AI', 'trung-tam-phat-trien-robot-ai', 'Nghiên cứu chế tạo các hệ thống cánh tay robot tự động hóa, xe tự hành (AGV) kết hợp trí tuệ nhân tạo nhận diện hình ảnh và tối ưu vận hành.', '{"version":1,"blocks":[{"id":"574eb6a4-577b-4b55-83ee-fa35cec273b2","type":"paragraph","text":"Nghiên cứu chế tạo các hệ thống cánh tay robot tự động hóa, xe tự hành (AGV) kết hợp trí tuệ nhân tạo nhận diện hình ảnh và tối ưu vận hành."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2024/03/ImageForArticle_702_172159750532-768x432.jpg', 'Trung tâm phát triển Robot & AI | VDCD', 'Nghiên cứu chế tạo các hệ thống cánh tay robot tự động hóa, xe tự hành (AGV) kết hợp trí tuệ nhân tạo nhận diện hình ảnh và tối ưu vận hành.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'e1760c66-386b-4de3-8490-5d71680649cf', 'solution-thumb-trung-tam-phat-trien-robot-ai', 'https://vdcd.vn/services/trung-tam-phat-trien-robot-ai/'),
  ('5c7a3230-66c9-4e2e-beef-9cbf31a2421e', 'Trung Tâm Sản Xuất Phim', 'trung-tam-san-xuat-phim', 'Sản xuất video clip giới thiệu dự án, quay phim khảo sát, flycam sự kiện chuyên nghiệp với trang thiết bị hiện đại hàng đầu.', '{"version":1,"blocks":[{"id":"69024f45-13f2-4b5a-b6d4-c178601f6e0a","type":"paragraph","text":"Sản xuất video clip giới thiệu dự án, quay phim khảo sát, flycam sự kiện chuyên nghiệp với trang thiết bị hiện đại hàng đầu."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2025/10/75474-768x576.jpg', 'Trung Tâm Sản Xuất Phim | VDCD', 'Sản xuất video clip giới thiệu dự án, quay phim khảo sát, flycam sự kiện chuyên nghiệp với trang thiết bị hiện đại hàng đầu.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '8cf42e59-62b2-44f9-9ab6-9adfa4ff12a7', 'solution-thumb-trung-tam-san-xuat-phim', 'https://vietflycam.vn/dich-vu/quay-phim-chup-anh-bang-flycam'),
  ('7b2d1698-d06a-4002-990d-f3557f027140', 'Trung tâm nghiên cứu và phát triển sản phẩm R&D', 'trung-tam-nghien-cuu-va-phat-trien-san-pham-rd', 'Đội ngũ chuyên gia chuyên nghiên cứu phát triển các sản phẩm phần cứng và giải pháp công nghệ mới bắt kịp xu hướng thế giới.', '{"version":1,"blocks":[{"id":"36ca0c97-311c-4835-a3a9-60c0d6fb9296","type":"paragraph","text":"Đội ngũ chuyên gia chuyên nghiên cứu phát triển các sản phẩm phần cứng và giải pháp công nghệ mới bắt kịp xu hướng thế giới."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2024/03/64576458-768x512.jpg', 'Trung tâm nghiên cứu và phát triển sản phẩm R&D | VDCD', 'Đội ngũ chuyên gia chuyên nghiên cứu phát triển các sản phẩm phần cứng và giải pháp công nghệ mới bắt kịp xu hướng thế giới.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'e1760c66-386b-4de3-8490-5d71680649cf', 'solution-thumb-trung-tam-nghien-cuu-va-phat-trien-san-pham-rd', 'https://vdcd.vn/services/trung-tam-nghien-cuu-va-phat-trien-san-pham/'),
  ('6e922f73-1e8a-4446-99e2-dbec49419db4', 'Nông nghiệp - Lâm nghiệp', 'nong-nghiep-lam-nghiep', 'Giải pháp nông nghiệp thông minh, giúp tối ưu hóa canh tác, tối ưu chi phí và truy xuất nguồn gốc dễ dàng.', '{"version":1,"blocks":[{"id":"8d899a26-cb75-4042-9363-60c1c5ca7ae4","type":"paragraph","text":"Giải pháp nông nghiệp thông minh, giúp tối ưu hóa canh tác, tối ưu chi phí và truy xuất nguồn gốc dễ dàng."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2026/06/Ban-sao-cua-IMG_2462-1024x768.jpg', 'Nông nghiệp - Lâm nghiệp | VDCD', 'Giải pháp nông nghiệp thông minh, giúp tối ưu hóa canh tác, tối ưu chi phí và truy xuất nguồn gốc dễ dàng.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', 'e20f8cfa-92dd-4302-a746-fe50562e19b4', 'solution-thumb-nong-nghiep-lam-nghiep', '/solution/nong-nghiep-lam-nghiep'),
  ('2b1ea734-43ae-48f9-833e-dda1b7df1551', 'Giám sát an ninh', 'an-ninh-giam-sat-an-ninh', 'Ứng dụng công nghệ AutoTimelapse giám sát trực quan 24/7, tự động cảnh báo xâm nhập và lưu trữ bảo mật.', '{"version":1,"blocks":[{"id":"5a6d49e1-9f64-4443-adb7-0ab53b1afc5c","type":"paragraph","text":"Ứng dụng công nghệ AutoTimelapse giám sát trực quan 24/7, tự động cảnh báo xâm nhập và lưu trữ bảo mật."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2026/06/z7896992273679_a63ab25fd7af7b68be795587ac4a41fb-1-1024x683.jpg', 'Giám sát an ninh | VDCD', 'Ứng dụng công nghệ AutoTimelapse giám sát trực quan 24/7, tự động cảnh báo xâm nhập và lưu trữ bảo mật.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-an-ninh-giam-sat-an-ninh', '/solution/an-ninh-giam-sat-an-ninh'),
  ('e39bd0a0-1f85-42fb-b9c3-268ad88bcb94', 'Điện - Năng lượng', 'dien-nang-luong', 'Hệ sinh thái số hóa tích hợp giúp tối ưu khảo sát, bảo trì lưới điện và giám sát an toàn.', '{"version":1,"blocks":[{"id":"44eb72ba-0844-4fb1-8297-edab6eb19448","type":"paragraph","text":"Hệ sinh thái số hóa tích hợp giúp tối ưu khảo sát, bảo trì lưới điện và giám sát an toàn."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2026/06/Dien-gio-Quang-Tri-1-1410x720.jpg', 'Điện - Năng lượng | VDCD', 'Hệ sinh thái số hóa tích hợp giúp tối ưu khảo sát, bảo trì lưới điện và giám sát an toàn.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-dien-nang-luong', '/solution/dien-nang-luong'),
  ('179fa443-256e-487d-8028-c2fa16567181', 'Khai thác khoáng sản', 'tai-nguyen-khai-thac-khoang-san', 'Giải pháp số hóa toàn diện khu vực mỏ giúp kiểm soát trạm cân, minh bạch hóa dữ liệu và tối ưu vận hành mỏ.', '{"version":1,"blocks":[{"id":"61f1ef8c-bbd5-45c2-8590-7339b34466d5","type":"paragraph","text":"Giải pháp số hóa toàn diện khu vực mỏ giúp kiểm soát trạm cân, minh bạch hóa dữ liệu và tối ưu vận hành mỏ."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2026/06/z7903688360376_37c98f8dadd2f5e6419362c107fe4ca4-1-1024x509.jpg', 'Khai thác khoáng sản | VDCD', 'Giải pháp số hóa toàn diện khu vực mỏ giúp kiểm soát trạm cân, minh bạch hóa dữ liệu và tối ưu vận hành mỏ.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-tai-nguyen-khai-thac-khoang-san', '/solution/tai-nguyen-khai-thac-khoang-san'),
  ('ae1465ef-94da-46df-b35f-d254f9e5f008', 'Tài nguyên môi trường', 'quan-ly-tai-nguyen-quan-trac-moi-truong', 'Giải pháp quan trắc môi trường giúp theo dõi dữ liệu thời gian thực, cảnh báo sớm rủi ro sinh thái.', '{"version":1,"blocks":[{"id":"a070b7c2-43c4-4f54-b998-d9fcfe16ab97","type":"paragraph","text":"Giải pháp quan trắc môi trường giúp theo dõi dữ liệu thời gian thực, cảnh báo sớm rủi ro sinh thái."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2026/06/z7913610376494_aabfc4669de386a5916480d8fb3f34cd-1024x490.jpg', 'Tài nguyên môi trường | VDCD', 'Giải pháp quan trắc môi trường giúp theo dõi dữ liệu thời gian thực, cảnh báo sớm rủi ro sinh thái.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5192c2da-2ca6-4c81-bbaa-fb0e9d4e02ae', 'solution-thumb-quan-ly-tai-nguyen-quan-trac-moi-truong', '/solution/quan-ly-tai-nguyen-quan-trac-moi-truong'),
  ('e621aa78-097e-4b73-8d2c-8b74c433b100', 'Du lịch thông minh - Số hóa di sản', 'du-lich-thong-minh-so-hoa-di-san', 'Ứng dụng công nghệ để số hóa di sản, xây dựng bản đồ du lịch thông minh và nâng tầm trải nghiệm thực tế ảo.', '{"version":1,"blocks":[{"id":"f818ce19-24cf-41aa-999e-eb1c1e4dbfbb","type":"paragraph","text":"Ứng dụng công nghệ để số hóa di sản, xây dựng bản đồ du lịch thông minh và nâng tầm trải nghiệm thực tế ảo."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2026/06/Lotte-Mall-1-1-1-scaled.jpg', 'Du lịch thông minh - Số hóa di sản | VDCD', 'Ứng dụng công nghệ để số hóa di sản, xây dựng bản đồ du lịch thông minh và nâng tầm trải nghiệm thực tế ảo.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '8cf42e59-62b2-44f9-9ab6-9adfa4ff12a7', 'solution-thumb-du-lich-thong-minh-so-hoa-di-san', '/solution/du-lich-thong-minh-so-hoa-di-san'),
  ('52a1acf2-6453-4eb5-9226-4a55b4a46b7c', 'Cứu hộ cứu nạn', 'cuu-ho-cuu-nan-phong-chong-thien-tai', 'Ứng dụng công nghệ tích hợp giúp cảnh báo sớm rủi ro thiên tai và hỗ trợ tìm kiếm cứu nạn.', '{"version":1,"blocks":[{"id":"2f098de1-d344-4c7a-ab9f-324265a109d6","type":"paragraph","text":"Ứng dụng công nghệ tích hợp giúp cảnh báo sớm rủi ro thiên tai và hỗ trợ tìm kiếm cứu nạn."}]}'::jsonb, 'https://vdcd.vn/wp-content/uploads/2026/06/z7908953163351_e6a394ecff68dca617c06ebed9a5ecbc-1024x768.jpg', 'Cứu hộ cứu nạn | VDCD', 'Ứng dụng công nghệ tích hợp giúp cảnh báo sớm rủi ro thiên tai và hỗ trợ tìm kiếm cứu nạn.', TRUE, '2026-08-31T20:04:50.107Z', '2026-08-31T20:04:50.107Z', '5292c9c5-7499-4353-9430-11aa730c63d8', 'solution-thumb-cuu-ho-cuu-nan-phong-chong-thien-tai', '/solution/cuu-ho-cuu-nan-phong-chong-thien-tai');

