INSERT INTO "article" (
  "id", "title", "slug", "content", "thumbnail", "thumbnail_file_id",
  "category", "tags", "meta_title", "meta_description",
  "is_published", "published_at", "created_at", "updated_at"
) VALUES (
  '11111111-aaaa-4111-a111-111111111101',
  'Trung tâm Đổi mới Sáng tạo Gia Lai ký kết MOU cùng Trường Đại học FPT, thúc đẩy đổi mới sáng tạo và phát triển nguồn nhân lực',
  'trung-tam-doi-moi-sang-tao-gia-lai-ky-ket-mou-cung-truong-dai-hoc-fpt-thuc-day-doi-moi-sang-tao-va-p',
  '{"version":1,"blocks":[{"id":"bc3c4d3f-772f-4527-8f5e-d09690ea4c0a","type":"paragraph","text":"Ngày 27/06/2026, tại Trường Đại học FPT Quy Nhơn AI Campus, Trung tâm Đổi mới Sáng tạo Gia Lai và Trường Đại học FPT đã chính thức ký kết Biên bản ghi nhớ hợp tác (MOU), mở ra giai đoạn hợp tác mới trong phát triển nguồn nhân lực chất lượng cao, kết nối hệ sinh thái đổi mới sáng tạo và triển khai các dự án ứng dụng công nghệ vào thực tiễn."},{"id":"801ee30c-d030-4f63-976d-1c3711207681","type":"paragraph","text":"Sự kiện diễn ra trong khuôn khổ Seminar “Văn hóa khởi nghiệp thời AI”, với sự tham dự của ông Cao Quân Vũ - Giám đốc Trung tâm Đổi mới Sáng tạo Gia Lai, đại diện Ban Giám hiệu Trường Đại học FPT cùng các đại biểu, giảng viên và sinh viên."},{"id":"157bece5-75c8-4f34-810b-c07e18932638","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_1_exact_2_E-oIRGdGQO_6N6EoxMxo.jpg","fileId":null,"alt":"Đại diện Trung tâm Đổi mới Sáng tạo Gia Lai và Trường Đại học FPT tại Lễ ký kết Biên bản ghi nhớ hợp tác (MOU) ngày 27/06/2026.","caption":"Đại diện Trung tâm Đổi mới Sáng tạo Gia Lai và Trường Đại học FPT tại Lễ ký kết Biên bản ghi nhớ hợp tác (MOU) ngày 27/06/2026."},{"id":"d4123562-874d-4e30-8fc1-d5786147256c","type":"heading","level":2,"text":"Đồng hành cùng thế hệ trẻ trong kỷ nguyên AI"},{"id":"0f64cbd9-0b9c-4075-aab0-9500e8150c04","type":"paragraph","text":"Trước lễ ký kết, đại diện Trung tâm Đổi mới Sáng tạo Gia Lai đã tham dự Seminar “Văn hóa khởi nghiệp thời AI” và lắng nghe những chia sẻ từ Thầy Trần Ngọc Tuấn – Phó Hiệu trưởng Trường Đại học FPT."},{"id":"3c1786d1-d3a3-4ecb-a4b9-5772fa7c8247","type":"paragraph","text":"Trong bối cảnh trí tuệ nhân tạo đang tác động mạnh mẽ đến phương thức học tập, làm việc và vận hành doanh nghiệp, khởi nghiệp không còn chỉ được nhìn nhận dưới góc độ thành lập một doanh nghiệp mới. Quan trọng hơn, đó là khả năng phát hiện vấn đề, chủ động tìm kiếm giải pháp, kiểm chứng ý tưởng và sử dụng công nghệ để tạo ra những giá trị thực tiễn. Tinh thần này cũng được Trường Đại học FPT nhấn mạnh trong các chương trình về “Văn hóa khởi nghiệp thời AI”: khởi nghiệp được mở rộng thành một năng lực tư duy, khuyến khích người trẻ chủ động đặt câu hỏi, nhìn nhận vấn đề từ nhiều góc độ và tìm ra lời giải mới thay vì đi theo những lối mòn sẵn có."},{"id":"4a2c4440-ad9a-40b7-8b3d-a5615cc9a984","type":"paragraph","text":"Đối với Trung tâm Đổi mới Sáng tạo Gia Lai, việc xây dựng tư duy đổi mới, tinh thần doanh chủ và năng lực ứng dụng công nghệ cho thế hệ trẻ là một trong những nền tảng quan trọng để hình thành nguồn nhân lực có khả năng thích ứng với tốc độ phát triển của AI và nền kinh tế số."},{"id":"861ffa22-cb07-4cdd-a579-7c162c0e5c42","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_1_exact_3_E-l1_mdSoe_lspDIwhJ9.jpg","fileId":null,"alt":"Sinh viên Trường Đại học FPT tham gia Seminar “Văn hóa khởi nghiệp thời AI” trong khuôn khổ chương trình ngày 27/06/2026.","caption":"Sinh viên Trường Đại học FPT tham gia Seminar “Văn hóa khởi nghiệp thời AI” trong khuôn khổ chương trình ngày 27/06/2026."},{"id":"8c210a58-6888-4ead-a053-052ff8847210","type":"paragraph","text":"Ký kết MOU - Mở rộng hợp tác giữa nhà trường và hệ sinh thái đổi mới sáng tạo"},{"id":"6363bef0-fa02-4bdc-98cf-c9b57c415d00","type":"paragraph","text":"Điểm nhấn của chương trình là Lễ ký kết Biên bản ghi nhớ hợp tác giữa Trung tâm Đổi mới Sáng tạo Gia Lai và Trường Đại học FPT."},{"id":"4dead5d8-5594-466b-8b2b-bd37bf960f25","type":"paragraph","text":"Việc ký kết đánh dấu bước phát triển mới trong quan hệ hợp tác giữa hai đơn vị, hướng đến tăng cường kết nối đào tạo, phát triển nguồn nhân lực, doanh nghiệp, công nghệ và đổi mới sáng tạo."},{"id":"0eda5eb8-1ec8-40ab-957c-bdff5969f1f5","type":"paragraph","text":"Thay vì giới hạn hoạt động hợp tác trong trao đổi học thuật, MOU hướng tới việc đưa nguồn lực của hai bên vào những chương trình và dự án có tính ứng dụng thực tế, qua đó tạo thêm cơ hội cho sinh viên tiếp cận môi trường doanh nghiệp, đồng thời thúc đẩy sự tham gia của nhà trường vào hệ sinh thái đổi mới sáng tạo tại địa phương."},{"id":"05ddebb3-d7f0-41c5-8fcf-761f5138a15d","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_1_exact_4_E-U9ia6qbb_pHQr981Hv.jpg","fileId":null,"alt":"Lễ ký kết MOU đánh dấu bước tiến mới trong quan hệ hợp tác giữa Trung tâm Đổi mới Sáng tạo Gia Lai và Trường Đại học FPT.","caption":"Lễ ký kết MOU đánh dấu bước tiến mới trong quan hệ hợp tác giữa Trung tâm Đổi mới Sáng tạo Gia Lai và Trường Đại học FPT."},{"id":"1a75ba15-7769-4e2f-95d4-27ecda78d4ee","type":"paragraph","text":"Ba định hướng hợp tác trọng tâm"},{"id":"73070490-8caf-4405-bb3e-8587895164f6","type":"paragraph","text":"Theo nội dung hợp tác, Trung tâm Đổi mới Sáng tạo Gia Lai và Trường Đại học FPT tập trung vào ba định hướng trọng tâm."},{"id":"70be4fb1-aa83-42f0-ae1d-22b8d1ead885","type":"paragraph","text":"Phát triển nguồn nhân lực chất lượng cao"},{"id":"cd31193d-62aa-42a7-9c22-7b48d97aa5b8","type":"paragraph","text":"Hai bên sẽ tăng cường kết nối trong hoạt động thực tập doanh nghiệp (On-the-Job Training – OJT), đào tạo gắn với thực tiễn và tuyển dụng, tạo điều kiện để sinh viên được tiếp xúc sớm với môi trường làm việc thực tế. Đây cũng là hướng tiếp cận phù hợp với mô hình đào tạo của Trường Đại học FPT. Sinh viên được học tập thông qua các dự án thực tế và có học kỳ đào tạo tại doanh nghiệp, từ đó từng bước chuyển hóa kiến thức chuyên môn thành năng lực giải quyết vấn đề trong môi trường nghề nghiệp."},{"id":"5027aade-1a49-4a10-8b69-c2a683fd12dd","type":"paragraph","text":"Thông qua sự hợp tác này, sinh viên có thêm cơ hội trải nghiệm các bài toán thực tế; trong khi doanh nghiệp và các tổ chức tại địa phương có thêm kênh tiếp cận nguồn nhân lực trẻ được đào tạo về công nghệ, tư duy số và đổi mới sáng tạo."},{"id":"2646150d-96d9-49ab-a515-ee2d6d288b5c","type":"paragraph","text":"Kết nối hệ sinh thái đổi mới sáng tạo"},{"id":"68d2a947-0737-4a59-a559-6bf925ab76a4","type":"paragraph","text":"Định hướng thứ hai là tăng cường kết nối giữa nhà trường, doanh nghiệp, chuyên gia, tổ chức hỗ trợ khởi nghiệp và hệ sinh thái đổi mới sáng tạo. Sự kết nối này có ý nghĩa quan trọng trong việc đưa những ý tưởng tiềm năng ra khỏi phạm vi giảng đường, tạo điều kiện để chúng được thử nghiệm, hoàn thiện và tiến gần hơn tới khả năng ứng dụng thực tế."},{"id":"bd277ecd-a8c0-4018-98ea-2ac3503e4f29","type":"paragraph","text":"Trong đó, Trung tâm Đổi mới Sáng tạo Gia Lai đóng vai trò cầu nối giữa các nguồn lực của địa phương với mạng lưới chuyên gia, doanh nghiệp và cơ sở đào tạo; qua đó góp phần thúc đẩy các hoạt động khởi nghiệp, ứng dụng công nghệ và chuyển đổi số."},{"id":"60526a07-2f11-4151-a9ef-e11c6770338d","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_1_exact_5_E-WP__uIYS_EVRSeL60W.jpg","fileId":null,"alt":"Hợp tác giữa hai đơn vị hướng đến tăng cường kết nối nhà trường, doanh nghiệp và hệ sinh thái đổi mới sáng tạo.","caption":"Hợp tác giữa hai đơn vị hướng đến tăng cường kết nối nhà trường, doanh nghiệp và hệ sinh thái đổi mới sáng tạo."},{"id":"ddb63f07-c289-4435-9f10-0a6b0ea5ecbe","type":"heading","level":2,"text":"Thúc đẩy các dự án ứng dụng thông qua Innovation Lab"},{"id":"f7b5926c-8157-4867-a44c-4cab32b2fc95","type":"paragraph","text":"Một nội dung đáng chú ý khác trong MOU là định hướng kết nối và triển khai các dự án chung thông qua mạng lưới Innovation Lab tại Trường Đại học FPT Quy Nhơn AI Campus. Các hoạt động này được kỳ vọng tạo môi trường để sinh viên, chuyên gia và các đơn vị liên quan cùng nghiên cứu, thử nghiệm và phát triển giải pháp cho những vấn đề thực tiễn."},{"id":"96d77532-e2b1-494d-9ea0-dd7e2bb4d3f8","type":"paragraph","text":"Trường Đại học FPT Quy Nhơn hiện là AI Campus duy nhất trong hệ thống Trường Đại học FPT, nằm trong hệ sinh thái nghiên cứu và phát triển trí tuệ nhân tạo tại Quy Nhơn. Môi trường đào tạo tại đây chú trọng việc kết hợp công nghệ, nghiên cứu, dự án thực tế và nhu cầu doanh nghiệp, đặc biệt trong các lĩnh vực như trí tuệ nhân tạo, kỹ thuật phần mềm, an toàn thông tin và thiết kế vi mạch bán dẫn."},{"id":"42f80659-db7e-446d-a886-b1392bb209ec","type":"paragraph","text":"Đây là nền tảng thuận lợi để những chương trình hợp tác trong khuôn khổ MOU từng bước được chuyển hóa thành các hoạt động nghiên cứu, thử nghiệm và ứng dụng cụ thể."},{"id":"8a2efbcf-3f58-4ed4-8fbd-fd3cb549cb1b","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_1_exact_6_E-d3FUsmt3__bLLPAWOE.jpg","fileId":null,"alt":"FPT Quy Nhơn AI Campus tạo môi trường kết nối đào tạo, nghiên cứu công nghệ và các dự án ứng dụng thực tiễn.","caption":"FPT Quy Nhơn AI Campus tạo môi trường kết nối đào tạo, nghiên cứu công nghệ và các dự án ứng dụng thực tiễn."},{"id":"02b737b5-dbc4-472f-ac40-e797dfb56aaf","type":"paragraph","text":"Hướng đến những giá trị hợp tác bền vững"},{"id":"10ce404e-ae96-407e-b442-3ba00e16af49","type":"paragraph","text":"Lễ ký kết MOU không chỉ đánh dấu mối quan hệ hợp tác giữa hai đơn vị mà còn thể hiện định hướng gắn kết nguồn lực giáo dục với nhu cầu phát triển thực tiễn của địa phương."},{"id":"26db893d-636a-4fa4-9de0-8f16968d9836","type":"paragraph","text":"Thông qua hợp tác cùng Trường Đại học FPT, Trung tâm Đổi mới Sáng tạo Gia Lai kỳ vọng từng bước mở rộng mạng lưới kết nối nguồn nhân lực, công nghệ, doanh nghiệp và các dự án đổi mới sáng tạo; đồng thời tạo thêm môi trường để người trẻ được học tập, trải nghiệm và phát triển các ý tưởng có khả năng giải quyết những bài toán thực tế."},{"id":"11e904bb-d0fe-4f21-9bd3-d4955d1c4da6","type":"paragraph","text":"Trong kỷ nguyên AI, lợi thế cạnh tranh không chỉ nằm ở khả năng tiếp cận công nghệ mới mà còn ở năng lực đưa công nghệ vào giải quyết vấn đề và tạo ra giá trị. Vì vậy, sự phối hợp giữa cơ sở đào tạo, doanh nghiệp và các tổ chức thúc đẩy đổi mới sáng tạo sẽ là một mắt xích quan trọng để hình thành nguồn nhân lực có năng lực thực hành, tư duy sáng tạo và khả năng thích ứng với thị trường lao động tương lai."},{"id":"a4f0f387-739e-45a6-a826-9316f6baef32","type":"paragraph","text":"Đại diện hai đơn vị cùng các bạn sinh viên Trường Đại Học  FPT  tại chương trình ký kết hợp tác ngày 27/06/2026."},{"id":"84feb1f2-243e-418a-8243-2bda1222ea25","type":"paragraph","text":"Việc ký kết MOU giữa Trung tâm Đổi mới Sáng tạo Gia Lai và Trường Đại học FPT vì thế là tiền đề để hai bên tiếp tục xây dựng những chương trình hợp tác cụ thể, từng bước đưa các cam kết từ biên bản ghi nhớ thành hoạt động thực tiễn, mang lại giá trị cho sinh viên, doanh nghiệp, cộng đồng và hệ sinh thái đổi mới sáng tạo của địa phương."}]}'::jsonb,
