) VALUES (
  '11111111-aaaa-4111-a111-111111111105',
  'Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026: Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số',
  'hoi-nghi-xuc-tien-dau-tu-tinh-gia-lai-nam-2026-chuyen-doi-mo-hinh-tang-truong-trong-ky-nguyen-so',
  '{"version":1,"blocks":[{"id":"dd26d843-7b1a-4d0e-be64-8bd45b22261e","type":"paragraph","text":"Ngày 28/03/2026, Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026 được tổ chức với chủ đề “Gia Lai - Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số”, thu hút sự tham dự của lãnh đạo Trung ương, lãnh đạo tỉnh, đại diện các cơ quan ngoại giao, tổ chức, chuyên gia, doanh nghiệp và nhà đầu tư trong và ngoài nước."},{"id":"7dfa8432-c877-4652-a714-76f01255c100","type":"paragraph","text":"Hội nghị là sự kiện quan trọng nhằm giới thiệu tiềm năng, lợi thế và định hướng phát triển của Gia Lai trong giai đoạn mới; đồng thời tạo không gian trao đổi trực tiếp giữa chính quyền, cộng đồng doanh nghiệp và các nhà đầu tư về những cơ hội hợp tác trong các lĩnh vực trọng điểm."},{"id":"aae66e3d-6db6-4a58-8e43-3357e980913a","type":"paragraph","text":"Thông qua Hội nghị, Gia Lai tiếp tục thể hiện quyết tâm cải thiện môi trường đầu tư, nâng cao năng lực cạnh tranh và chuyển đổi mô hình tăng trưởng theo hướng dựa trên khoa học – công nghệ, đổi mới sáng tạo, chuyển đổi số và các ngành có giá trị gia tăng cao."},{"id":"b022e3a1-9f6b-4b01-a760-c0cb7297b406","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_5_exact_2_E-F3XuEq5H_KdY3qRNha.jpg","fileId":null,"alt":"Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026: Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số","caption":null},{"id":"ec8bc347-b8a0-4d89-967e-e1968e498ddf","type":"paragraph","text":"Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026 với chủ đề “Gia Lai - Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số”."},{"id":"81d11ad8-9e64-4975-8297-0682d67c75f1","type":"paragraph","text":"Gia Lai xác định những động lực tăng trưởng mới"},{"id":"d09d0a17-efcb-4681-867d-34664fa2411d","type":"paragraph","text":"Tại Hội nghị, lãnh đạo tỉnh Gia Lai đã thông tin về tiềm năng, lợi thế, định hướng phát triển cũng như các lĩnh vực ưu tiên thu hút đầu tư trong thời gian tới."},{"id":"89575ebd-f597-42b7-8641-4345b37c6045","type":"paragraph","text":"Bước vào giai đoạn phát triển mới, Gia Lai xác định mục tiêu không chỉ gia tăng quy mô đầu tư mà còn chú trọng chất lượng, hiệu quả và khả năng tạo động lực phát triển dài hạn của các dự án."},{"id":"8e19c027-3873-48cb-b271-47938b8456c6","type":"paragraph","text":"Các lĩnh vực được tỉnh quan tâm thu hút đầu tư gồm công nghiệp chế biến – chế tạo, năng lượng tái tạo, nông nghiệp công nghệ cao, thương mại – dịch vụ, du lịch, logistics cùng những ngành công nghệ mới như trí tuệ nhân tạo (AI) và chip bán dẫn."},{"id":"89e26ca5-9e7f-40d8-93d0-46a4a4bac17a","type":"paragraph","text":"Việc mở rộng danh mục ưu tiên sang những ngành có hàm lượng công nghệ và tri thức cao cho thấy định hướng từng bước chuyển đổi cơ cấu kinh tế, nâng cao năng suất và hình thành những động lực tăng trưởng mới phù hợp với xu thế phát triển của nền kinh tế số."},{"id":"3ee58b9f-7825-4371-b2a5-15717b9759c2","type":"paragraph","text":"Đồng thời, Gia Lai tiếp tục phát huy các lợi thế về vị trí địa lý, quỹ đất, tài nguyên, tiềm năng năng lượng và nông nghiệp để thu hút những dự án có khả năng tạo ra chuỗi giá trị và sức lan tỏa đối với kinh tế – xã hội địa phương."},{"id":"44625892-ed07-490e-a952-77b0a1f36b6c","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_5_exact_3_E-s4pitHBJ_xoba7pAwA.jpg","fileId":null,"alt":"Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026: Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số","caption":null},{"id":"97df635c-f32f-4748-8cea-6aaf5ea95ef5","type":"paragraph","text":"Chủ tịch UBND tỉnh Phạm Anh Tuấn thông tin những định hướng lớn về thu hút đầu tư của tỉnh Gia Lai."},{"id":"109ec682-5441-4d85-9a23-4f0638120297","type":"paragraph","text":"Tại hội nghị, các chuyên gia đã có những phân tích chuyên sâu về lợi thế, tiềm năng phát triển, cơ hội đầu tư, thương mại của tỉnh Gia Lai; chia sẻ kinh nghiệm thực tiễn phong phú cùng tầm nhìn chiến lược về phát triển du lịch hiện đại gắn với bảo tồn tài nguyên và bản sắc văn hóa; gợi mở định hướng phát triển bền vững của tỉnh Gia Lai trong giai đoạn tới bằng việc chuyển đổi mô hình tăng trưởng từ “mô hình tăng trưởng chủ yếu dựa vào vốn” sang “mô hình tăng trưởng chủ yếu dựa vào  tri thức” - Đổi mới sáng tạo,chuyển đổi xanh và chuyển đổi số nhằm khai thác tiềm năng và các lợi thế vượt trội."},{"id":"35f57382-2592-4daf-85a5-ebe82759a266","type":"paragraph","text":"Các nhà đầu tư mong muốn tiếp tục nhận được sự đồng hành của tỉnh Gia Lai và các đối tác để biến những định hướng thành các dự án cụ thể, tạo giá trị thiết thực cho người dân, góp phần thúc đẩy kinh tế địa phương phát triển trong dài hạn."},{"id":"04a1f595-b5dc-4cf5-bcc7-b7b7efe2907e","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_5_exact_4_E-oPsGaDA6_b2gHi7WEa.jpg","fileId":null,"alt":"Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026: Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số","caption":null},{"id":"8fc04f10-1b70-479d-b924-625ce6bb9aa5","type":"paragraph","text":"Cải thiện môi trường đầu tư, đồng hành cùng doanh nghiệp"},{"id":"e6d1d2a9-fb2f-4881-81d8-428c7804794c","type":"paragraph","text":"Một trong những nội dung được nhấn mạnh tại Hội nghị là quyết tâm tiếp tục cải thiện môi trường đầu tư, kinh doanh và nâng cao chất lượng phục vụ doanh nghiệp. Gia Lai đang tập trung hoàn thiện quy hoạch, chuẩn bị quỹ đất, đầu tư kết cấu hạ tầng, đẩy mạnh cải cách hành chính và rút ngắn thời gian giải quyết các thủ tục liên quan đến dự án đầu tư."},{"id":"819525c1-1ba8-4906-ae6e-e5abd74e2645","type":"paragraph","text":"Theo thông tin được công bố tại Hội nghị, thời gian giải quyết thủ tục đối với dự án ngoài khu kinh tế, khu công nghiệp đã được rút từ 242 ngày xuống còn 60 ngày; đối với dự án trong khu kinh tế, khu công nghiệp, thời gian được rút từ 145 ngày xuống còn 38 ngày."},{"id":"d1d80ed2-f710-49e9-a51e-13e96d13d0ae","type":"paragraph","text":"Việc đơn giản hóa quy trình, nâng cao tính minh bạch và tăng cường ứng dụng công nghệ trong quản lý được kỳ vọng góp phần giảm chi phí, tiết kiệm thời gian cho doanh nghiệp và tạo điều kiện thuận lợi hơn trong quá trình triển khai dự án."},{"id":"a91e9b09-7025-4a62-b224-d2dc206eed39","type":"paragraph","text":"Tinh thần xuyên suốt được tỉnh xác định là chuyển mạnh từ tư duy quản lý sang đồng hành, hỗ trợ và phục vụ doanh nghiệp, nhà đầu tư, kịp thời tháo gỡ những khó khăn, vướng mắc phát sinh trong quá trình thực hiện dự án."},{"id":"cb90d50c-b505-465e-9388-55592909ee1e","type":"paragraph","text":"Doanh nghiệp và chuyên gia trao đổi về cơ hội phát triển tại Gia Lai"},{"id":"e4cef00b-5eda-4e14-90ca-9c99768c0ab8","type":"paragraph","text":"Trong khuôn khổ Hội nghị, các đại biểu, chuyên gia và đại diện cộng đồng doanh nghiệp đã có nhiều trao đổi xoay quanh tiềm năng, cơ hội đầu tư và những giải pháp thúc đẩy tăng trưởng của tỉnh trong thời gian tới."},{"id":"404ba498-b224-4a0a-8edf-382b92c92920","type":"paragraph","text":"Các ý kiến tập trung vào yêu cầu phát huy hiệu quả lợi thế hiện có, đồng thời thúc đẩy ứng dụng khoa học – công nghệ, đổi mới sáng tạo và chuyển đổi số nhằm nâng cao năng suất và sức cạnh tranh của nền kinh tế."},{"id":"5726145a-d02c-43f5-b90c-2b6e0cc8d90c","type":"paragraph","text":"Đáng chú ý, các lĩnh vực AI, bán dẫn, kinh tế số và công nghệ cao được đề cập như những hướng đi mới có khả năng bổ sung cho các thế mạnh truyền thống của địa phương."},{"id":"711c4172-54bc-46a3-af6e-d939f5c73892","type":"paragraph","text":"Bên cạnh thu hút nguồn vốn, các ý kiến cũng nhấn mạnh vai trò của nguồn nhân lực, chất lượng hạ tầng, khả năng kết nối doanh nghiệp với các cơ sở nghiên cứu, đào tạo và việc hình thành môi trường thuận lợi cho hoạt động đổi mới sáng tạo."},{"id":"14dcc80f-774a-48a1-9d47-208e0791966d","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_5_exact_5_E-JJrmep80_JscBYPzzC.jpg","fileId":null,"alt":"Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026: Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số","caption":null},{"id":"1989bc2c-bba6-46bf-824c-d37d412a971e","type":"paragraph","text":"TS.Trần Du Lịch - Thành viên hội đồng tư vấn tài chính tiền tệ quốc gia bàn giải pháp về chuyển đổi mô hình tăng trưởng"},{"id":"157f0e8d-f720-44c4-9e12-fa9281eb9e90","type":"paragraph","text":"Bên cạnh thu hút nguồn vốn, các ý kiến cũng nhấn mạnh vai trò của nguồn nhân lực, chất lượng hạ tầng, khả năng kết nối doanh nghiệp với các cơ sở nghiên cứu, đào tạo và việc hình thành môi trường thuận lợi cho hoạt động đổi mới sáng tạo."},{"id":"e00d1139-6577-4d12-90b6-7fd9593e2cf1","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_5_exact_6_E-v2J1GYKV_H4WUOBr33.jpg","fileId":null,"alt":"Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026: Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số","caption":null},{"id":"caf63467-b69d-432a-823b-9a6864cdbd4a","type":"paragraph","text":"Phó Thủ tướng Chính phủ Hồ Quốc Dũng phát biểu chỉ đạo."},{"id":"1e4c5d02-58ec-4c76-800e-6d02ab7f5d02","type":"paragraph","text":"Phát biểu tại hội nghị, Phó Thủ tướng Chính phủ Hồ Quốc Dũng đánh giá Hội nghị xúc tiến đầu tư tỉnh Gia Lai năm 2026 là sự kiện có ý nghĩa quan trọng, mang tầm chiến lược, thể hiện rõ tầm nhìn và khát vọng phát triển mạnh mẽ của địa phương trong việc cụ thể hóa các định hướng phát triển mới của đất nước và của tỉnh trong giai đoạn tới."},{"id":"5487fcda-7089-489e-abd5-538467918161","type":"paragraph","text":"Theo Phó Thủ tướng, năm 2026 là năm đầu tiên triển khai Nghị quyết Đại hội lần thứ XIV của Đảng, với yêu cầu cao về tốc độ, chất lượng và tính bền vững của tăng trưởng, đặc biệt hướng tới mục tiêu tăng trưởng 02 con số trong giai đoạn 2026–2030. Trong bối cảnh đó, việc Gia Lai xây dựng kịch bản tăng trưởng GRDP đạt 10,2% cho năm 2026 được đánh giá là phù hợp với định hướng chung, thể hiện tư duy phát triển chủ động, quyết tâm chính trị cao và tinh thần dám nghĩ, dám làm."},{"id":"2469f8e6-b8fe-4490-afec-ec057369126c","type":"paragraph","text":"Phó Thủ tướng cũng ghi nhận nỗ lực của tỉnh trong việc từng bước tái định hình mô hình tăng trưởng theo hướng hiện đại, bền vững, dựa trên các trụ cột như công nghiệp chế biến, công nghệ cao, năng lượng tái tạo và dịch vụ giá trị gia tăng. Đây được xem là hướng đi đúng, phù hợp với chiến lược phát triển chung của cả nước trong giai đoạn tới."},{"id":"51e0b6a1-9bb5-4af6-980a-57b4d7513bf6","type":"paragraph","text":"Để khai thác hiệu quả tiềm năng, lợi thế và tạo đà bứt phá, Phó Thủ tướng đề nghị Gia Lai tập trung triển khai nghiêm túc, hiệu quả các nghị quyết của Đảng; đồng thời thực hiện quyết liệt 5 trụ cột tăng trưởng và 4 khâu đột phá chiến lược theo Nghị quyết Đại hội Đảng bộ tỉnh, bảo đảm sự thống nhất cao trong toàn hệ thống chính trị."},{"id":"bf1a8863-991c-42c4-9049-dfe5daff1c12","type":"paragraph","text":"Bên cạnh đó, tỉnh cần nâng cao hiệu quả xúc tiến, thu hút đầu tư theo hướng có chọn lọc, trọng tâm, trọng điểm; chuyển mạnh từ thu hút theo số lượng sang chú trọng chất lượng, hiệu quả và tính bền vững. Ưu tiên các dự án ứng dụng công nghệ tiên tiến, thân thiện môi trường, có khả năng lan tỏa và tạo giá trị gia tăng cao."},{"id":"d1d32d09-4093-4307-9d5b-cde1a7aff1e3","type":"paragraph","text":"Phó Thủ tướng cũng nhấn mạnh yêu cầu triển khai hiệu quả các nghị quyết của Bộ Chính trị trên tất cả các lĩnh vực, trong đó chú trọng thực hiện Nghị quyết số 68-NQ/TW về phát triển kinh tế tư nhân. Đồng thời, đẩy mạnh cải cách hành chính theo hướng thực chất, lấy sự hài lòng của người dân và doanh nghiệp làm thước đo; tăng cường chuyển đổi số, minh bạch hóa quy trình, giảm thời gian và chi phí cho doanh nghiệp. Cùng với đó là yêu cầu xây dựng đội ngũ cán bộ, công chức có năng lực, trách nhiệm, kỷ luật, kỷ cương; chủ động đồng hành, hỗ trợ doanh nghiệp, kịp thời tháo gỡ khó khăn, vướng mắc trong phạm vi thẩm quyền."},{"id":"b21d035d-d16a-47e5-ad35-5e46d4feb37e","type":"paragraph","text":"Phó Thủ tướng Hồ Quốc Dũng bày tỏ tin tưởng, với quyết tâm cao và tinh thần hành động quyết liệt, Đảng bộ, chính quyền và Nhân dân tỉnh Gia Lai sẽ tiếp tục phát huy truyền thống đoàn kết, đổi mới tư duy, khơi dậy khát vọng phát triển, nắm bắt cơ hội và vượt qua thách thức để thực hiện thắng lợi các mục tiêu, nhiệm vụ đã đề ra."},{"id":"cdb70bc8-9489-48fe-bafc-9b0ab5e6ef85","type":"paragraph","text":"Trao quyết định và ký kết hợp tác đối với 273 dự án"},{"id":"c48f48ff-766d-444f-bedd-9953cb0b9916","type":"paragraph","text":"Điểm nhấn quan trọng tại Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026 là hoạt động trao quyết định chấp thuận chủ trương đầu tư, giấy chứng nhận đăng ký đầu tư và ký kết các biên bản ghi nhớ hợp tác."},{"id":"64608b3f-f76d-4e40-8213-e6bef0490bd8","type":"paragraph","text":"Theo thông tin tại Hội nghị, có 273 dự án được trao quyết định, giấy chứng nhận và ký kết biên bản ghi nhớ, với tổng vốn đăng ký và dự kiến đầu tư khoảng 850.000 tỷ đồng, tương đương hơn 33 tỷ USD."},{"id":"0e81c34d-d35c-4842-be7c-5f9e307c18e9","type":"paragraph","text":"Các dự án thuộc nhiều lĩnh vực khác nhau, bao gồm công nghiệp chế biến – chế tạo, năng lượng, nông nghiệp công nghệ cao, thương mại, dịch vụ, du lịch, đô thị và logistics."},{"id":"a005df2a-7200-4c97-9074-1e60e2e553ef","type":"paragraph","text":"Kết quả này cho thấy sự quan tâm của cộng đồng doanh nghiệp, nhà đầu tư đối với môi trường và tiềm năng phát triển của Gia Lai, đồng thời tạo cơ sở để địa phương tiếp tục mở rộng các nguồn lực phục vụ mục tiêu tăng trưởng trong giai đoạn tới."},{"id":"68c08ff6-b0bb-4da8-be4a-d253953863d8","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_5_exact_7_E-E-oajKOn_QouM-f6GB.jpg","fileId":null,"alt":"Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026: Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số","caption":null},{"id":"5e1458d2-c5e7-413f-968e-9cb9bf9149bd","type":"paragraph","text":"Bí thư Tỉnh ủy Thái Đại Ngọc và Chủ tịch UBND tỉnh Phạm Anh Tuấn tặng hoa và trao Giấy chứng nhận đăng ký đầu tư cho dự án Trung Tâm Đổi Mới Sáng Tạo"},{"id":"16bfdd42-e19e-4caf-a8aa-99fe4e8f1a34","type":"paragraph","text":"Khoa học, công nghệ và đổi mới sáng tạo trong mô hình tăng trưởng mới"},{"id":"ff676737-0aaf-4c7d-b5dd-ded247758dcc","type":"paragraph","text":"Với chủ đề “Chuyển đổi mô hình tăng trưởng trong kỷ nguyên số”, Hội nghị năm nay dành sự quan tâm đáng kể đến vai trò của khoa học – công nghệ, đổi mới sáng tạo và chuyển đổi số."},{"id":"f8be4bb8-5294-4d5c-b5bb-a21ec8136439","type":"paragraph","text":"Trong bối cảnh yêu cầu nâng cao năng suất và chất lượng tăng trưởng ngày càng trở nên cấp thiết, việc ứng dụng công nghệ được xác định là một trong những giải pháp quan trọng giúp doanh nghiệp đổi mới hoạt động sản xuất, kinh doanh và quản trị."},{"id":"bb4a5fc4-34c5-42bb-b412-842a65b60c5f","type":"paragraph","text":"Đối với những lĩnh vực có thế mạnh của Gia Lai như nông nghiệp, công nghiệp chế biến, năng lượng, logistics và du lịch, các công nghệ về dữ liệu, trí tuệ nhân tạo, tự động hóa và nền tảng số có thể hỗ trợ nâng cao hiệu quả vận hành, tăng khả năng kết nối và từng bước hình thành các chuỗi giá trị có hàm lượng công nghệ cao hơn."},{"id":"f6126fa8-9a71-43d9-ae8f-cbfd4de9cff7","type":"paragraph","text":"Song song đó, việc phát triển hệ sinh thái đổi mới sáng tạo, tăng cường kết nối giữa cơ quan quản lý, doanh nghiệp, trường đại học, viện nghiên cứu và các tổ chức khoa học – công nghệ sẽ tạo nền tảng để các sáng kiến, kết quả nghiên cứu và giải pháp công nghệ có thêm điều kiện ứng dụng vào thực tiễn.."},{"id":"4766341d-6f9d-43bc-a044-be71cea54e03","type":"paragraph","text":"Tạo nền tảng cho giai đoạn phát triển 2026-2030"},{"id":"2b63079d-972a-4d35-81ef-8b96db4db504","type":"paragraph","text":"Hội nghị Xúc tiến đầu tư tỉnh Gia Lai năm 2026 không chỉ là dịp giới thiệu danh mục dự án và tìm kiếm nguồn lực đầu tư mà còn thể hiện rõ định hướng phát triển của tỉnh trong giai đoạn mới."},{"id":"c447fc94-839a-47d0-9fc2-d91c1caca96a","type":"paragraph","text":"Từ cải thiện môi trường kinh doanh, hoàn thiện hạ tầng, thu hút các dự án quy mô lớn đến phát triển khoa học – công nghệ, chuyển đổi số và nguồn nhân lực, Gia Lai đang từng bước chuẩn bị những điều kiện cần thiết để chuyển đổi mô hình tăng trưởng theo hướng hiện đại, bền vững và có giá trị gia tăng cao."},{"id":"5ea578ef-7ec9-450a-9f0b-3a2e6d7e7776","type":"paragraph","text":"Kết quả của Hội nghị, đặc biệt là những thỏa thuận và dự án được công bố, là tiền đề để tỉnh tiếp tục phối hợp với doanh nghiệp và nhà đầu tư trong quá trình triển khai các chương trình, dự án cụ thể."},{"id":"adb6ef2a-609f-4047-b4a5-6ca0d12e6c28","type":"paragraph","text":"Trong thời gian tới, việc hiện thực hóa các cam kết đầu tư, đồng hành tháo gỡ khó khăn cho doanh nghiệp và tăng cường kết nối các nguồn lực sẽ có ý nghĩa quan trọng đối với mục tiêu phát triển kinh tế – xã hội của Gia Lai."},{"id":"5b749893-7847-4c98-9730-2b47ba61268b","type":"paragraph","text":"Với những định hướng được xác lập tại Hội nghị, Gia Lai tiếp tục khẳng định quyết tâm xây dựng môi trường đầu tư minh bạch, thuận lợi, đẩy mạnh ứng dụng khoa học – công nghệ và đổi mới sáng tạo, qua đó tạo nền tảng cho giai đoạn tăng trưởng mới trong kỷ nguyên số."},{"id":"11e090d6-a5a0-43b4-a914-ccc08c2f54e4","type":"paragraph","text":"Bí thư Tỉnh ủy Thái Đại Ngọc phát biểu bế mạc hội nghị."},{"id":"84d21dc2-e6b2-4239-9060-fd6100e929f4","type":"paragraph","text":"Thay mặt Đảng bộ, chính quyền và Nhân dân tỉnh Gia Lai, Bí thư Tỉnh ủy Thái Đại Ngọc bày tỏ lời cảm ơn tới Chính phủ, các Đại sứ, Tổng Lãnh sự, các bộ, ban, ngành Trung ương, đại diện tổ chức quốc tế, cùng các chuyên gia, nhà khoa học, doanh nghiệp và nhà đầu tư đã đồng hành, đóng góp nhiều ý kiến thiết thực, chia sẻ kinh nghiệm quý và đưa ra các khuyến nghị chính sách, đề xuất hợp tác cụ thể, góp phần vào thành công của hội nghị."},{"id":"28ade9ed-c6d6-4d35-a763-ef12a1d525e7","type":"paragraph","text":"Bí thư Tỉnh ủy cho biết tỉnh nghiêm túc tiếp thu đầy đủ các ý kiến chỉ đạo sâu sắc, toàn diện và mang tính định hướng chiến lược của Phó Thủ tướng Chính phủ tại hội nghị."},{"id":"0f713c35-4887-4a39-a458-543eba1ee6ce","type":"paragraph","text":"Khẳng định quyết tâm của địa phương, Bí thư Tỉnh uỷ Thái Đại Ngọc cam kết tỉnh Gia Lai sẽ khẩn trương xây dựng kế hoạch triển khai cụ thể, phân công rõ trách nhiệm, tiến độ và kết quả; đồng thời tăng cường kiểm tra, giám sát, bảo đảm các chỉ đạo của Chính phủ được thực hiện hiệu quả, thực chất, tạo chuyển biến rõ nét trong môi trường đầu tư và phát triển kinh tế - xã hội."},{"id":"b03027be-2462-40df-80fa-a1bd4a1a69ec","type":"paragraph","text":"Bí thư Tỉnh ủy cũng bày tỏ tin tưởng sự cộng hưởng giữa các hoạt động của Năm Du lịch Quốc gia 2026 với Hội nghị xúc tiến đầu tư sẽ tạo hiệu ứng lan tỏa mạnh mẽ, góp phần thu hút nguồn lực đầu tư, thúc đẩy phát triển kinh tế - xã hội của tỉnh theo hướng nhanh và bền vững trong thời gian tới."}]}'::jsonb,
