  '11111111-aaaa-4111-a111-111111111107',
  'VDCD đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi, thúc đẩy chuyển đổi số toàn diện',
  'vdcd-de-xuat-thanh-lap-trung-tam-doi-moi-sang-tao-tinh-quang-ngai-thuc-day-chuyen-doi-so-toan-dien',
  '{"version":1,"blocks":[{"id":"6b1728b2-7df5-4e61-ac22-05a55d144a01","type":"paragraph","text":"Chiều ngày 09/06/2026, Công ty Cổ phần Tổng Công ty Công nghệ Thiết kế Xây dựng Việt Nam (VDCD) đã có buổi làm việc với UBND tỉnh Quảng Ngãi, trình bày đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi cùng hệ sinh thái các giải pháp công nghệ phục vụ chuyển đổi số. Đề xuất hướng đến xây dựng hạ tầng dữ liệu đồng bộ, tăng cường ứng dụng công nghệ trong quản lý, điều hành và tạo nền tảng phát triển hệ sinh thái đổi mới sáng tạo tại địa phương."},{"id":"56891853-a239-4e4a-ab7e-1125ed7950e2","type":"paragraph","text":"Buổi làm việc do Phó Chủ tịch UBND tỉnh Quảng Ngãi Trần Phước Hiền chủ trì, với sự tham dự của đại diện các sở, ngành, đơn vị liên quan và VDCD."},{"id":"b41cd1f7-5bfa-41ec-b0d1-eed1ffd42794","type":"paragraph","text":"Tại chương trình, hai bên tập trung trao đổi về các giải pháp đổi mới sáng tạo, hạ tầng dữ liệu và ứng dụng công nghệ trong những lĩnh vực trọng điểm, từ quản lý đất đai, quy hoạch, xây dựng đến tài nguyên môi trường, phòng chống thiên tai, du lịch và xúc tiến đầu tư."},{"id":"7a8c2f8e-70f6-4ba1-bac1-467b351a32de","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_7_exact_2_E-hE1yA8ie_eoNl2cqFg.jpg","fileId":null,"alt":"VDCD đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi, thúc đẩy chuyển đổi số toàn diện","caption":null},{"id":"10394a47-f78e-4b20-ae45-85e4b11da15d","type":"paragraph","text":"Phó Chủ tịch UBND tỉnh Quảng Ngãi Trần Phước Hiền chủ trì buổi làm việc về các giải pháp đổi mới sáng tạo và chuyển đổi số do VDCD đề xuất."},{"id":"35a4acf7-c2cd-4d46-89e4-68fb137e9cf9","type":"heading","level":2,"text":"Đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi"},{"id":"0c9432a6-5480-4f69-ad34-9463d80399e9","type":"paragraph","text":"Một trong những nội dung trọng tâm được VDCD trình bày tại buổi làm việc là đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi."},{"id":"0de77a01-2992-4b51-9139-a17e9a14f390","type":"paragraph","text":"Theo định hướng đề xuất, Trung tâm sẽ đóng vai trò đầu mối trong việc xây dựng và vận hành hạ tầng dữ liệu của tỉnh, từng bước hình thành hệ thống có khả năng lưu trữ, xử lý, phân tích và hiển thị dữ liệu, phục vụ công tác quản lý, điều hành và hỗ trợ quá trình ra quyết định dựa trên dữ liệu."},{"id":"7a00b260-0c26-4020-9106-16a590142ebe","type":"paragraph","text":"Bên cạnh hạ tầng dữ liệu, Trung tâm được định hướng phát triển các nền tảng công nghệ phục vụ quản trị nhà nước, hoạt động của doanh nghiệp và những ngành kinh tế trọng điểm của địa phương."},{"id":"48c94dba-21ad-4625-b974-bea82794d4e0","type":"paragraph","text":"Đồng thời, đây cũng sẽ là điểm kết nối giữa cơ quan quản lý, doanh nghiệp, chuyên gia, các cơ sở nghiên cứu  đào tạo và cộng đồng khởi nghiệp, góp phần thúc đẩy nghiên cứu, chuyển giao và đưa các giải pháp công nghệ vào thực tiễn."},{"id":"967b33af-a36c-4d9e-872f-ef0d74fb96bc","type":"paragraph","text":"Mô hình này hướng tới mục tiêu hình thành một hệ sinh thái đổi mới sáng tạo gắn với những yêu cầu phát triển cụ thể của tỉnh, trong đó dữ liệu và công nghệ đóng vai trò nền tảng."},{"id":"fe9577d8-1e5d-4c79-85a5-85b192c7e3cc","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_7_exact_3_E-0X86Mk9X_MrtJa-avQ.jpg","fileId":null,"alt":"VDCD đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi, thúc đẩy chuyển đổi số toàn diện","caption":null},{"id":"64323160-2c04-4e15-8537-691c4350362a","type":"paragraph","text":"Đại diện VDCD trình bày đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi và định hướng xây dựng hạ tầng dữ liệu phục vụ quản lý, điều hành."},{"id":"fa466d1c-7c83-4eee-beb6-cca751ac8f65","type":"paragraph","text":"Hệ sinh thái công nghệ tích hợp phục vụ chuyển đổi số"},{"id":"fe4dc9c9-c00d-43a0-a1f4-8419a4e841e8","type":"paragraph","text":"Tại buổi làm việc, VDCD cũng giới thiệu hệ sinh thái giải pháp công nghệ tích hợp được xây dựng theo chuỗi từ thu thập dữ liệu, xử lý mô hình hóa,  lưu trữ,  khai thác và ứng dụng. Ở lớp thu thập dữ liệu, các công nghệ như UAV, thiết bị quét số và IoT có thể hỗ trợ khảo sát, đo đạc, số hóa hiện trạng và cập nhật dữ liệu từ thực tế."},{"id":"59a6fd43-ed48-4440-8404-fa2f67700519","type":"paragraph","text":"Dữ liệu sau khi thu thập được xử lý và mô hình hóa thông qua các nền tảng công nghệ như BIM (Building Information Modeling), GIS (Geographic Information System) và trí tuệ nhân tạo (AI), tạo cơ sở để hình thành các mô hình dữ liệu trực quan, có khả năng phân tích và phục vụ nhiều nghiệp vụ quản lý khác nhau."},{"id":"08bb53d7-8091-4b8e-adde-9d96d76f0258","type":"paragraph","text":"Một thành phần quan trọng khác trong hệ sinh thái là trung tâm dữ liệu cấp tỉnh, đóng vai trò hạ tầng phục vụ lưu trữ, xử lý và khai thác dữ liệu. Cùng với đó là các phần mềm hành chính công, cổng dữ liệu mở và chương trình đào tạo, chuyển giao công nghệ, giúp các giải pháp không chỉ được triển khai về mặt kỹ thuật mà còn từng bước hình thành năng lực khai thác và vận hành tại địa phương."},{"id":"eea6d539-a8fe-4b03-9887-98977334a62b","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_7_exact_4_E-KPhdvukA_f2wSwXRR0.jpg","fileId":null,"alt":"VDCD đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi, thúc đẩy chuyển đổi số toàn diện","caption":null},{"id":"45a298ff-c51b-4702-a429-5bdaf41c5f89","type":"paragraph","text":"Hệ sinh thái giải pháp VDCD kết nối UAV, IoT, BIM, GIS, AI và hạ tầng dữ liệu phục vụ quá trình chuyển đổi số."},{"id":"5de44c59-57d1-4f8c-876d-85bc91d95e95","type":"paragraph","text":"Xây dựng cơ sở dữ liệu không gian số phục vụ quản lý đất đai và quy hoạch"},{"id":"083926be-5865-4bdc-9294-ba42ca5e73f0","type":"paragraph","text":"Đối với Quảng Ngãi, VDCD đề xuất triển khai nhiều nhóm giải pháp gắn trực tiếp với nhu cầu quản lý của địa phương."},{"id":"b1067ff3-0f7d-4b41-8572-44ae4ebed35c","type":"paragraph","text":"Trong đó, một trong những nội dung trọng tâm là xây dựng cơ sở dữ liệu không gian số 2D và 3D, phục vụ công tác quản lý đất đai, quy hoạch và phát triển đô thị."},{"id":"f766f367-044a-4284-988a-a28154a40ee9","type":"paragraph","text":"Khi dữ liệu không gian được số hóa và tổ chức trên một nền tảng thống nhất, các cơ quan chuyên môn có thêm công cụ phục vụ theo dõi hiện trạng, phân tích thông tin và hỗ trợ công tác quản lý."},{"id":"6fd50b3b-5196-4806-8654-f3f5d224e974","type":"paragraph","text":"Hệ thống đồng thời có thể hỗ trợ giám sát biến động đất đai, theo dõi trật tự xây dựng, số hóa quy hoạch thông qua mô hình số và sa bàn ảo."},{"id":"e285b276-8239-4f13-b80d-09d57b95cd8c","type":"paragraph","text":"Đối với lĩnh vực xây dựng, việc ứng dụng BIM được đề xuất nhằm hỗ trợ quản lý thông tin công trình và các dự án đầu tư xây dựng, từng bước nâng cao khả năng phối hợp và quản lý dữ liệu xuyên suốt quá trình triển khai dự án."},{"id":"966e0a78-8084-463a-844e-bccf8c6340e6","type":"paragraph","text":"Ứng dụng dữ liệu trong tài nguyên, môi trường và phòng chống thiên tai"},{"id":"1a9a9701-162a-4b8a-acd4-5acb2bdcb869","type":"paragraph","text":"Không gian ứng dụng của hệ thống dữ liệu được đề xuất mở rộng sang lĩnh vực tài nguyên và môi trường."},{"id":"3cbaec3f-4924-46b4-a59d-33cc21df502f","type":"paragraph","text":"VDCD đề xuất xây dựng các cơ sở dữ liệu chuyên ngành phục vụ quản lý tài nguyên, môi trường, giám sát rừng và hệ sinh thái, qua đó tăng khả năng tổng hợp, theo dõi và khai thác thông tin phục vụ công tác quản lý."},{"id":"aae719c3-2069-4893-8f02-8fbb44cc0ecb","type":"paragraph","text":"Cùng với đó, dữ liệu không gian, công nghệ quan trắc và các nền tảng phân tích có thể được nghiên cứu ứng dụng trong phòng chống thiên tai và cảnh báo sớm rủi ro."},{"id":"54384699-e3a9-4e11-8293-df7f598ec785","type":"paragraph","text":"Đây là nhóm bài toán đòi hỏi dữ liệu từ nhiều nguồn phải được cập nhật, tổng hợp và phân tích kịp thời. Vì vậy, việc hình thành một hạ tầng dữ liệu có khả năng liên kết giữa các lĩnh vực là điều kiện quan trọng để nâng cao hiệu quả khai thác thông tin."},{"id":"2c4c9936-f9aa-495d-8cd4-6a0eafc4272b","type":"paragraph","text":"Số hóa du lịch và hỗ trợ xúc tiến đầu tư"},{"id":"d232a35c-60d6-494a-9b58-fa4296b56733","type":"paragraph","text":"Bên cạnh quản lý nhà nước, hệ sinh thái công nghệ được VDCD đề xuất còn hướng đến các lĩnh vực phát triển kinh tế của Quảng Ngãi."},{"id":"bf26ecc2-c88b-49d4-b1e4-8210843638dc","type":"paragraph","text":"Trong lĩnh vực du lịch, doanh nghiệp đề xuất số hóa các điểm du lịch, di tích và xây dựng bản đồ số du lịch của tỉnh, tạo thêm nền tảng để quản lý, giới thiệu và khai thác dữ liệu về điểm đến."},{"id":"9d413a76-a1d5-4995-b51e-75abfb6d40c1","type":"paragraph","text":"Đối với hoạt động xúc tiến đầu tư, việc xây dựng cơ sở dữ liệu tập trung có thể hỗ trợ tổng hợp và trực quan hóa thông tin về quy hoạch, hạ tầng, địa điểm và những nguồn lực liên quan, giúp quá trình tiếp cận thông tin thuận lợi hơn."},{"id":"9a40e792-3b69-4003-bc57-c359d1f0c6c0","type":"paragraph","text":"Các giải pháp về định danh địa điểm, đánh số nhà trên nền tảng số và phát triển đô thị thông minh cũng được đưa ra để nghiên cứu, hướng đến từng bước hoàn thiện hệ thống dữ liệu không gian phục vụ quản lý và phát triển đô thị."},{"id":"9411f50c-b852-4c44-b3f2-5d430b0da6b4","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_7_exact_5_E-blB-Ifb__nxD-wAzvX.jpg","fileId":null,"alt":"VDCD đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi, thúc đẩy chuyển đổi số toàn diện","caption":null},{"id":"f052056f-c63c-41ea-b1a4-4c4d4b047552","type":"paragraph","text":"Đại diện các sở, ngành tỉnh Quảng Ngãi trao đổi về khả năng ứng dụng các giải pháp công nghệ vào nhu cầu thực tế của từng lĩnh vực."},{"id":"d4706208-153c-46a2-abe6-cec43f2975fd","type":"paragraph","text":"Hướng đến quản lý và điều hành dựa trên dữ liệu"},{"id":"b8091862-93f4-436c-9cad-ee3c80b53ddb","type":"paragraph","text":"Một trong những mục tiêu xuyên suốt của các giải pháp được trình bày là nâng cao khả năng khai thác dữ liệu phục vụ quản lý, chỉ đạo và điều hành."},{"id":"c8bdd9d6-bf42-42c2-9328-9191149d683f","type":"paragraph","text":"Thay vì dữ liệu tồn tại riêng lẻ tại từng hệ thống hoặc từng lĩnh vực, định hướng tích hợp giúp hình thành nguồn dữ liệu có khả năng kết nối, trực quan hóa và hỗ trợ phân tích."},{"id":"c18f4147-2a82-4f0d-8bec-d05d3319fee9","type":"paragraph","text":"Qua đó, dữ liệu không chỉ được lưu trữ mà từng bước trở thành một nguồn lực phục vụ quá trình ra quyết định."},{"id":"7dedb602-fb3e-49cf-ae98-ffda6a954b5a","type":"paragraph","text":"Đây cũng là nền tảng quan trọng trong quá trình phát triển chính quyền số và kinh tế số, khi chất lượng quản trị ngày càng gắn với khả năng thu thập, chuẩn hóa, kết nối và khai thác dữ liệu một cách hiệu quả."},{"id":"3e97a8b0-5cbb-4a11-a4c8-87b054b5656b","type":"paragraph","text":"Nghiên cứu triển khai Trung tâm Đổi mới sáng tạo theo quy định"},{"id":"201b7a5d-1839-4664-b5a8-939d30947f2b","type":"paragraph","text":"Kết luận buổi làm việc, Phó Chủ tịch UBND tỉnh Quảng Ngãi Trần Phước Hiền ghi nhận và đánh giá cao các giải pháp đổi mới sáng tạo, chuyển đổi số do VDCD trình bày; đồng thời nhận định các giải pháp có tính ứng dụng, phù hợp với nhu cầu quản lý, điều hành trong bối cảnh tỉnh đang đẩy mạnh chuyển đổi số, xây dựng chính quyền số và phát triển kinh tế số."},{"id":"d9151fc1-65f4-4a93-8da4-3c2f47601f81","type":"paragraph","text":"Phó Chủ tịch UBND tỉnh đề nghị các sở, ngành và địa phương chủ động trao đổi với doanh nghiệp để nghiên cứu, lựa chọn những giải pháp phù hợp với nhu cầu thực tế của từng lĩnh vực."},{"id":"0ff95b29-a653-4b5b-af5a-83211b832a09","type":"paragraph","text":"Đáng chú ý, Sở Khoa học và Công nghệ được giao chủ trì, phối hợp với Sở Tài chính và các cơ quan liên quan làm việc với VDCD để nghiên cứu việc thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi theo quy định."},{"id":"1410b0ff-ed7b-493b-a5fd-7a10153ee8bd","type":"paragraph","text":"Các cơ quan liên quan đồng thời được giao phối hợp nghiên cứu, đánh giá tính khả thi của những đề xuất cụ thể, bảo đảm phù hợp với quy hoạch, định hướng phát triển và quy định pháp luật."},{"id":"f5df59f0-3968-43d3-a9e7-912e5c4f162e","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_7_exact_6_E-TpSwgbA8_DJDTZq1Em.jpg","fileId":null,"alt":"VDCD đề xuất thành lập Trung tâm Đổi mới sáng tạo tỉnh Quảng Ngãi, thúc đẩy chuyển đổi số toàn diện","caption":null},{"id":"b9fd89ad-e269-473d-ba49-daabd98807b1","type":"paragraph","text":"Phó Chủ tịch UBND tỉnh Quảng Ngãi Trần Phước Hiền kết luận buổi làm việc về các giải pháp đổi mới sáng tạo và chuyển đổi số."},{"id":"644d5386-8f81-4c78-a048-5875341b98f1","type":"paragraph","text":"Buổi làm việc ngày 09/06/2026 là bước trao đổi quan trọng để VDCD và các cơ quan của tỉnh Quảng Ngãi tiếp tục nghiên cứu khả năng triển khai những giải pháp công nghệ phù hợp với điều kiện thực tế của địa phương."},{"id":"d85d2be4-7da1-48a4-a5b7-b3353b72536b","type":"paragraph","text":"Từ hạ tầng dữ liệu, BIM, GIS, AI đến các ứng dụng trong đất đai, quy hoạch, tài nguyên, xây dựng và du lịch, đề xuất hướng đến một mục tiêu chung: xây dựng nền tảng dữ liệu đồng bộ, tăng cường ứng dụng khoa học – công nghệ và từng bước hình thành hệ sinh thái đổi mới sáng tạo phục vụ phát triển kinh tế – xã hội của tỉnh Quảng Ngãi."}]}'::jsonb,
  'https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_7_exact_1_E-8vcADZi1_rR_uRYAEF.jpg',
  '6a9a8738ead997d09a116e2c',
