) VALUES (
  '11111111-aaaa-4111-a111-111111111108',
  'Trung tâm Đổi mới Sáng tạo Gia Lai làm việc với Sở Tài nguyên và Môi trường tỉnh Lâm Đồng về giải pháp chuyển đổi số xanh',
  'trung-tam-doi-moi-sang-tao-gia-lai-lam-viec-voi-so-tai-nguyen-va-moi-truong-tinh-lam-dong-ve-giai-ph',
  '{"version":1,"blocks":[{"id":"95cbfc0f-df4e-4c5b-b91f-90315ff33fb5","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai đã có buổi làm việc với Sở Tài nguyên và Môi trường tỉnh Lâm Đồng nhằm trao đổi về các giải pháp công nghệ phục vụ chuyển đổi số xanh. Tại chương trình, Trung tâm Đổi mới Sáng tạo Gia Lai tập trung giới thiệu phương án số hóa dữ liệu không gian, giám sát biến động tài nguyên và xây dựng nền tảng quản lý tích hợp, hướng đến phục vụ Đề án Chuyển đổi xanh dựa vào thiên nhiên của tỉnh Lâm Đồng."},{"id":"4b319d01-f6af-41fc-87ce-83e896f7484c","type":"paragraph","text":"Buổi làm việc là dịp để hai bên trao đổi về khả năng ứng dụng công nghệ vào công tác quản lý tài nguyên, đặc biệt đối với các nhóm dữ liệu về đất đai, rừng, vùng trồng, mặt nước và hạ tầng. Trên cơ sở những yêu cầu thực tế, Trung tâm Đổi mới Sáng tạo Gia Lai trình bày hệ sinh thái giải pháp tích hợp nhiều công nghệ gồm viễn thám, UAV, mô hình 3D, Digital Twin, trí tuệ nhân tạo (AI) và nền tảng GIS, qua đó từng bước hình thành nguồn dữ liệu không gian có khả năng cập nhật, quản lý và khai thác tập trung."},{"id":"fda346e9-b836-4248-bc1c-9e152681d6dd","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_8_exact_2_E-LrP55GHr_fj12DT1Oc.jpg","fileId":null,"alt":"Trung tâm Đổi mới Sáng tạo Gia Lai làm việc với Sở Tài nguyên và Môi trường tỉnh Lâm Đồng về giải pháp chuyển đổi số xanh","caption":null},{"id":"15d60c35-376a-4bb9-9151-41f2bbac5435","type":"paragraph","text":"Đại diện Trung tâm Đổi mới Sáng tạo Gia Lai  trao đổi cùng Sở Tài nguyên và Môi trường tỉnh Lâm Đồng về giải pháp chuyển đổi số xanh và xây dựng nền tảng dữ liệu không gian."},{"id":"b9468252-49b8-4087-a0d9-da1b91e20c1a","type":"paragraph","text":"Số hóa dữ liệu phục vụ quản lý tài nguyên"},{"id":"dbd35965-42c5-478d-bec6-ae4bdcc79df2","type":"paragraph","text":"Tại buổi làm việc, Trung tâm Đổi mới Sáng tạo Gia Lai xác định số hóa dữ liệu hiện trạng là một trong những nền tảng quan trọng để nâng cao hiệu quả quản lý và theo dõi tài nguyên. Theo giải pháp được trình bày, dữ liệu không gian về đất đai, rừng, vùng trồng, mặt nước và hạ tầng có thể được thu thập, số hóa và quản lý trên nền tảng thống nhất. Mỗi khu vực, vùng, lô và đối tượng quản lý được xác lập tọa độ, diện tích, ranh giới và mã định danh, tạo cơ sở cho việc tra cứu và cập nhật dữ liệu."},{"id":"28d6cd5e-aaf1-4aec-a57c-1662f964f852","type":"paragraph","text":"Trên nền dữ liệu đã được chuẩn hóa, hệ thống hướng đến hỗ trợ theo dõi sự thay đổi của đất đai, rừng, cây trồng, mặt nước và các khu vực phục hồi sinh thái qua từng thời kỳ. Dữ liệu đồng thời có thể được trực quan hóa trên bản đồ số và dashboard, giúp cơ quan chuyên môn thuận lợi hơn trong quá trình tra cứu, phân tích và giám sát hiện trạng."},{"id":"362f3c96-83d2-4a98-ae00-7a5210b82676","type":"image","url":"https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_8_exact_3_E-b7xm_kA-_GVeXLm8K2.jpg","fileId":null,"alt":"Trung tâm Đổi mới Sáng tạo Gia Lai làm việc với Sở Tài nguyên và Môi trường tỉnh Lâm Đồng về giải pháp chuyển đổi số xanh","caption":null},{"id":"cfceea50-682f-4f58-a5db-fdd209980edc","type":"paragraph","text":"Trung tâm Đổi mới Sáng tạo Gia Lai trình bày phương án số hóa và chuẩn hóa dữ liệu không gian phục vụ công tác quản lý tài nguyên."},{"id":"07b01791-df41-45bc-9ff8-f5d259efb6dc","type":"paragraph","text":"Ứng dụng đồng bộ Viễn thám, UAV, AI và GIS"},{"id":"7306f791-50da-42d7-bfe7-0d268650ec6d","type":"paragraph","text":"Một trong những nội dung trọng tâm được Trung tâm Đổi mới Sáng tạo Gia Lai giới thiệu là khả năng kết hợp nhiều công nghệ trong quá trình thu thập, xử lý và khai thác dữ liệu."},{"id":"85ebfdd7-ebb0-40a8-8c73-59605d1e2dbc","type":"paragraph","text":"Viễn thám hỗ trợ khai thác ảnh vệ tinh có độ phân giải cao và cập nhật định kỳ để theo dõi biến động địa hình, sử dụng đất trên diện rộng. Trong khi đó, UAV được sử dụng để thu thập dữ liệu hiện trạng có độ phân giải cao, phục vụ đo đạc, thành lập bản đồ 2D, 3D và hỗ trợ kiểm tra thực địa."},{"id":"0d3966c9-35d6-4f3a-b41a-2c6f7f2eabd9","type":"paragraph","text":"Dữ liệu thu thập được có thể tiếp tục xây dựng thành mô hình không gian 3D, tạo góc nhìn trực quan hơn về hiện trạng khu vực. Giải pháp Digital Twin cũng được đề xuất nhằm hình thành bản sao số, hỗ trợ mô phỏng và nghiên cứu các kịch bản phát triển."},{"id":"c96d3aec-7c94-44a0-a678-c4d6b8335b19","type":"paragraph","text":"Toàn bộ các lớp dữ liệu được định hướng tích hợp trên GIS Platform, tạo nền tảng quản lý tập trung và chia sẻ dữ liệu không gian."},{"id":"60b2521b-17e9-47c3-aaec-8a9427cc21c4","type":"paragraph","text":"Bên cạnh đó, trí tuệ nhân tạo được ứng dụng để hỗ trợ tự động nhận diện, phân loại và xử lý một số nhóm đối tượng từ dữ liệu thu thập được."},{"id":"a8db2c1d-53ac-4098-ae97-8f5c938afd3a","type":"heading","level":2,"text":"Đề xuất ứng dụng công nghệ vào quản lý rừng"},{"id":"f980a546-75da-4f4c-bffa-6fdeef643997","type":"paragraph","text":"Nội dung về quản lý và số hóa dữ liệu rừng được trao đổi cụ thể thông qua các mô hình ứng dụng. Trung tâm Đổi mới Sáng tạo Gia Lai trình bày giải pháp xây dựng bản đồ 2D hiện trạng, mô hình 3D và không gian quan sát VR360, cho phép số hóa hiện trạng rừng dưới nhiều hình thức trực quan."},{"id":"83d272dd-0bc6-4304-a482-ce9db0db0916","type":"paragraph","text":"Trên nền tảng 3D GIS, dữ liệu có thể hỗ trợ đo đạc diện tích, đánh giá mật độ rừng, xác định chiều cao cây và quản lý thông tin theo từng ranh giới. Khả năng quan sát và tra cứu dữ liệu từ xa cũng góp phần hỗ trợ công tác chuyên môn, giảm tần suất kiểm tra thực địa trong những trường hợp không cần thiết."},{"id":"425e6622-5989-4bfb-b943-9372ea75d281","type":"paragraph","text":"Đáng chú ý, Trung tâm Đổi mới Sáng tạo Gia Lai giới thiệu phương án ứng dụng AI kết hợp dữ liệu UAV/GIS để nhận diện ranh giới thửa đất, vùng trồng, khoảnh rừng, mặt nước và các đối tượng hiện trạng."},{"id":"f32b692b-20fe-4f59-ab4e-b9f4457668f6","type":"paragraph","text":"AI cũng có thể hỗ trợ nhận diện và đếm cây từ dữ liệu hình ảnh, sau đó liên kết kết quả với hệ thống quản lý để phục vụ tra cứu."},{"id":"6c2b2c9f-169d-4301-8f8b-73057c769744","type":"paragraph","text":"Định danh dữ liệu, theo dõi biến động theo thời gian"},{"id":"7b676cb7-efd1-44a8-8bae-99ac9957c816","type":"paragraph","text":"Bên cạnh số hóa hiện trạng, giải pháp của Trung tâm Đổi mới Sáng tạo Gia Lai hướng đến việc định danh từng đối tượng quản lý. Sau khi nhận diện ranh giới, từng vùng rừng có thể được gắn thông tin và mã quản lý riêng. Qua đó, dữ liệu không chỉ thể hiện vị trí trên bản đồ mà còn được liên kết với các thuộc tính phục vụ kiểm kê, giám sát biến động và truy xuất thông tin."},{"id":"b01c1c98-cfbd-41c9-a9e4-227c3a4d89e1","type":"paragraph","text":"Việc duy trì dữ liệu theo từng thời kỳ tạo điều kiện so sánh sự thay đổi của hiện trạng, hỗ trợ cơ quan chuyên môn theo dõi biến động trên phạm vi rộng và xác định những khu vực cần được kiểm tra, đánh giá sâu hơn."},{"id":"c6068a0b-4f4f-4899-b96d-39d0b7dcc772","type":"paragraph","text":"Cách tiếp cận này hướng đến chuyển đổi từ quan sát hiện trạng sang quản lý dựa trên dữ liệu, trong đó thông tin được chuẩn hóa, cập nhật và khai thác trên cùng một nền tảng."},{"id":"bf370445-a7c2-406e-9307-deafb0bee154","type":"paragraph","text":"Hai bên trao đổi về khả năng khai thác dữ liệu số phục vụ kiểm kê, giám sát biến động và công tác quản lý."},{"id":"79bfa309-2832-4690-84ae-4331c22a305d","type":"paragraph","text":"Hướng đến nền tảng dữ liệu phục vụ chuyển đổi xanh tại Lâm Đồng"},{"id":"f7f1fa3b-c932-4525-9799-410167643a10","type":"paragraph","text":"Thông qua buổi làm việc, Trung tâm Đổi mới Sáng tạo Gia Lai đề xuất một mô hình công nghệ theo hướng đồng bộ, tích hợp dữ liệu viễn thám, UAV, 2D/3D, AI và GIS trên nền tảng quản lý thống nhất."},{"id":"d4ae5a85-b90d-45cb-9b6a-074ddfc50858","type":"paragraph","text":"Giải pháp được xây dựng theo hướng có khả năng mở rộng, nhằm đáp ứng nhu cầu cập nhật và phát triển trong từng giai đoạn, đồng thời tập trung vào khả năng ứng dụng đối với các bài toán quản lý thực tế."},{"id":"69b9ca17-b756-4a29-8331-fcc7d015bd6a","type":"paragraph","text":"Trên cơ sở các nội dung đã trao đổi, Trung tâm Đổi mới Sáng tạo Gia Lai sẵn sàng phối hợp cùng tỉnh Lâm Đồng và các đơn vị liên quan trong công tác khảo sát, số hóa hiện trạng và xây dựng nền tảng dữ liệu không gian phục vụ Đề án Chuyển đổi xanh dựa vào thiên nhiên, hướng đến quản lý chủ động, minh bạch và phát triển bền vững."},{"id":"e005e022-cd90-4d75-aa08-1d4697c50121","type":"paragraph","text":"Buổi làm việc đồng thời tạo cơ sở để các bên tiếp tục trao đổi, đánh giá những nhóm giải pháp phù hợp với yêu cầu thực tế, qua đó nghiên cứu khả năng ứng dụng công nghệ và dữ liệu không gian trong quá trình chuyển đổi số xanh tại Lâm Đồng."}]}'::jsonb,
  'https://ik.imagekit.io/po0s6zxoj/vdcd/articles/art_8_exact_1_E-kx7c_DH8_Nkb290pep.jpg',
  '6a9a874aead997d09a11e7b0',
  'Chuyển đổi số',
  'chuyển đổi số xanh Lâm Đồng, Trung tâm Đổi mới Sáng tạo Gia Lai, Sở Tài nguyên và Môi trường Lâm Đồng, số hóa tài nguyên, GIS Lâm Đồng, UAV, AI GIS, số hóa dữ liệu rừng, dữ liệu không gian.',
  'Trung tâm Đổi mới Sáng tạo Gia Lai làm việc với Sở Tài nguyên và Môi trường tỉnh Lâm Đồng về giải pháp chuyển đổi số xanh | VDCD Gia Lai',
  'Trung tâm Đổi mới Sáng tạo Gia Lai đã có buổi làm việc với Sở Tài nguyên và Môi trường tỉnh Lâm Đồng nhằm trao đổi về các giải pháp công nghệ phục vụ chuyển đổi số xanh. Tại chương trình, Trung tâm Đổi mới Sáng tạo Gia Lai tập trung giới thiệu phương...',
